        rr, rm, rl = rng.uniform(0.1, 10.0, 3)
        lhs = beta * ((rr + rr / 3.0) + (rm + 0.0) + (rl + (-rl)))
        rhs = beta * ((4.0 / 3.0) * rr + rm)
        res_cancel = max(res_cancel, abs(lhs - rhs) / max(abs(rhs), 1e-30))
