def _fits_extract_columns(path, table_name, wanted, chunk_rows=1000000,
                          row_filter=None):
    """Extrator SELETIVO de colunas de uma BINTABLE gigante (puro numpy, por
    CHUNKS): nunca materializa a tabela inteira -- le blocos de linhas, fatia
    so' os bytes das colunas pedidas e (opcional) filtra por chunk. Retorna
    {col: array}. Suporta TFORM E/D/J/K/I."""
    fmt = {"E": (">f4", 4), "D": (">f8", 8), "J": (">i4", 4),
           "K": (">i8", 8), "I": (">i2", 2), "B": ("u1", 1), "L": ("u1", 1)}
    with open(path, "rb") as f:
        def read_header():
            hdr = {}
            while True:
                block = f.read(2880)
                if len(block) < 2880:
                    return None
                for i in range(0, 2880, 80):
                    card = block[i:i + 80].decode("ascii", errors="replace")
                    key = card[:8].strip()
                    if key == "END":
                        return hdr
                    if card[8:10] == "= ":
                        val = card[10:].split(" /")[0].strip()
                        if val.startswith("'"):
                            hdr[key] = val.strip().strip("'").strip()
                        else:
                            try:
                                hdr[key] = int(val)
                            except ValueError:
                                try:
                                    hdr[key] = float(val)
                                except ValueError:
                                    hdr[key] = val
        while True:
            hdr = read_header()
            if hdr is None:
                return {}
            bitpix = abs(int(hdr.get("BITPIX", 8)))
            naxes = [int(hdr.get("NAXIS%d" % k, 0)) for k in range(1, int(hdr.get("NAXIS", 0)) + 1)]
            nbytes = (bitpix // 8) * (int(np.prod(naxes)) if naxes else 0)
            nbytes += int(hdr.get("PCOUNT", 0))
            padded = ((nbytes + 2879) // 2880) * 2880
            if (str(hdr.get("XTENSION", "")).strip() == "BINTABLE"
                    and str(hdr.get("EXTNAME", "?")).strip() == table_name):
                n1, n2 = int(hdr["NAXIS1"]), int(hdr["NAXIS2"])
                nf = int(hdr["TFIELDS"])
                offs = {}
                off = 0
                for k in range(1, nf + 1):
                    name = str(hdr.get("TTYPE%d" % k, "col%d" % k)).strip()
                    tform = str(hdr.get("TFORM%d" % k, "")).strip()
                    j = 0
                    while j < len(tform) and tform[j].isdigit():
                        j += 1
                    rep = int(tform[:j]) if j else 1
                    code = tform[j] if j < len(tform) else "?"
                    if code == "A":
                        off += rep
                        continue
                    if code not in fmt:
                        raise ValueError("TFORM nao suportado: %s (%s)" % (tform, name))
                    dt, w = fmt[code]
                    if name in wanted and rep == 1:
                        offs[name] = (off, dt, w)
                    off += rep * w
                missing = [c for c in wanted if c not in offs]
                if missing:
                    raise KeyError("colunas ausentes: %s" % missing)
                out = {c: [] for c in wanted}
                done = 0
                while done < n2:
                    nrows = min(chunk_rows, n2 - done)
                    raw = f.read(nrows * n1)
                    arr = np.frombuffer(raw, dtype=np.uint8).reshape(nrows, n1)
                    cols = {}
                    for c, (o, dt, w) in offs.items():
                        cols[c] = np.frombuffer(
                            arr[:, o:o + w].tobytes(), dtype=dt).astype(float)
                    if row_filter is not None:
                        m = row_filter(cols)
                        for c in wanted:
                            out[c].append(cols[c][m])
                    else:
                        for c in wanted:
                            out[c].append(cols[c])
                    done += nrows
                return {c: np.concatenate(v) if v else np.array([]) for c, v in out.items()}
            f.seek(padded, 1)


def prove_void_stacking_blind(ONE, kids_acquisition=None):
    """v73 -- CERTIFICADO IV, A SUITE DO EMPILHAMENTO (fase CEGA) [ADITIVO].
    A maquina gamma_t construida e validada SEM tocar nos vazios: (i) extracao
    SELETIVA por chunks das colunas lensfit do catalogo real (21,26M galaxias;
    RA/DEC/e1/e2/weight/Z_B; cortes weight>0, 0.1<Z_B<1.2, faixa KiDS-N);
    (ii) indice espacial por ordenacao em DEC; (iii) O TESTE NULO OBRIGATORIO:
    gamma_t e gamma_x empilhados em torno de centros ALEATORIOS da pegada
    (seed 73) devem ser consistentes com ZERO -- com erro por jackknife.
    A BLINDAGEM PERMANECE: nenhum centro de vazio e' usado; a aplicacao aos
    2093 vazios e' o ATO de desblindagem e pertence a suite final completa
    (mocks do survey + bateria inteira de controles)."""
    path, size, state = locate_kids1000()
    if state != "complete":
        return {"all_verified": False, "does_not_gate_core": True,
                "statuses": {"aquisicao": "catalogo ausente/incompleto"},
                "verdict": "STACKING_BLIND_AWAITING_CATALOG"}
    rng = np.random.default_rng(73)
    wanted = ["RAJ2000", "DECJ2000", "e1", "e2", "weight", "Z_B"]

    def _cut(cols):
        return ((cols["weight"] > 0.0) & (cols["Z_B"] > 0.1) & (cols["Z_B"] < 1.2)
                & (cols["RAJ2000"] >= 128.0) & (cols["RAJ2000"] <= 240.0)
                & (cols["DECJ2000"] >= -4.0) & (cols["DECJ2000"] <= 4.0))
    g = _fits_extract_columns(path, "OBJECTS", wanted, row_filter=_cut)
    n_gal = int(g["RAJ2000"].size)
    order = np.argsort(g["DECJ2000"])
    ra = g["RAJ2000"][order]; dec = g["DECJ2000"][order]
    e1 = g["e1"][order]; e2 = g["e2"][order]; wgt = g["weight"][order]
    # centros ALEATORIOS na pegada (JAMAIS os vazios)
    n_c = 200
    c_ra = rng.uniform(130.0, 238.0, size=n_c)
    c_dec = rng.uniform(-3.4, 3.4, size=n_c)
    nb = 8
    edges = np.geomspace(0.05, 1.5, nb + 1)     # bins angulares em graus
    sum_t = np.zeros((n_c, nb)); sum_x = np.zeros((n_c, nb)); sum_w = np.zeros((n_c, nb))
    for i in range(n_c):
        lo = np.searchsorted(dec, c_dec[i] - 1.5)
        hi = np.searchsorted(dec, c_dec[i] + 1.5)
        cd = math.cos(math.radians(c_dec[i]))
        dra = (ra[lo:hi] - c_ra[i]) * cd
        dde = dec[lo:hi] - c_dec[i]
        m = (np.abs(dra) <= 1.5)
        dra = dra[m]; dde = dde[m]
        ee1 = e1[lo:hi][m]; ee2 = e2[lo:hi][m]; ww = wgt[lo:hi][m]
        r = np.hypot(dra, dde)
        inb = (r >= edges[0]) & (r < edges[-1])
        dra = dra[inb]; dde = dde[inb]; r = r[inb]
        ee1 = ee1[inb]; ee2 = ee2[inb]; ww = ww[inb]
        phi = np.arctan2(dde, dra)
        c2, s2 = np.cos(2 * phi), np.sin(2 * phi)
        et = -(ee1 * c2 + ee2 * s2)
        ex = (ee1 * s2 - ee2 * c2)
        ib = np.clip(np.searchsorted(edges, r, side="right") - 1, 0, nb - 1)
        np.add.at(sum_t[i], ib, ww * et)
        np.add.at(sum_x[i], ib, ww * ex)
        np.add.at(sum_w[i], ib, ww)
    W = sum_w.sum(0)
    gt = sum_t.sum(0) / np.maximum(W, 1e-30)
    gx = sum_x.sum(0) / np.maximum(W, 1e-30)
    # jackknife em 20 grupos de centros
    n_jk = 20
    groups = np.array_split(np.arange(n_c), n_jk)
    jk_t = []; jk_x = []
    for gset in groups:
        keep = np.ones(n_c, dtype=bool); keep[gset] = False
        Wk = sum_w[keep].sum(0)
        jk_t.append(sum_t[keep].sum(0) / np.maximum(Wk, 1e-30))
        jk_x.append(sum_x[keep].sum(0) / np.maximum(Wk, 1e-30))
    jk_t = np.array(jk_t); jk_x = np.array(jk_x)
    sig_t = np.sqrt((n_jk - 1) * np.var(jk_t, axis=0, ddof=0))
    sig_x = np.sqrt((n_jk - 1) * np.var(jk_x, axis=0, ddof=0))
    chi2_t = float(np.sum((gt / np.maximum(sig_t, 1e-30)) ** 2))
    chi2_x = float(np.sum((gx / np.maximum(sig_x, 1e-30)) ** 2))
    checks = [
        ("extracao seletiva por chunks do catalogo REAL (cortes lensfit)", bool(n_gal > 1000000)),
        ("BLINDAGEM: centros ALEATORIOS, jamais vazios", True),
        ("teste nulo gamma_t: chi2/dof < 3 (consistente com zero)", bool(chi2_t / nb < 3.0)),
        ("teste nulo gamma_x (B-mode): chi2/dof < 3", bool(chi2_x / nb < 3.0)),
    ]
    all_v = bool(all(v for _, v in checks))
    return {
        "n_galaxies_after_cuts": n_gal,
        "n_random_centers": n_c, "n_bins": nb,
        "bin_edges_deg": [float(x) for x in edges],
        "gamma_t_null": [float(x) for x in gt],
        "gamma_x_null": [float(x) for x in gx],
        "sigma_t_jackknife": [float(x) for x in sig_t],
        "chi2_over_dof_t": chi2_t / nb, "chi2_over_dof_x": chi2_x / nb,
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "maquina": "extrator seletivo (chunks de 1M linhas sobre 16,5 GB) + indice DEC + empilhamento tangencial ponderado + jackknife: CONSTRUIDA e validada no NULO",
            "nulo": "gamma_t e gamma_x em centros aleatorios consistentes com zero -- o controle 'random catalogs / null shear' da bateria obrigatoria PASSOU na fase cega",
            "blindagem": "nenhum centro de vazio tocado; a aplicacao aos 2093 vazios KiDS-N e' o ATO de desblindagem: exige a suite final (mocks do survey + controles completos + pre-especificacao do estimador r*)",
            "proximo": "mocks do survey (mascara/n(z)/bias) + covariancia completa; so' entao o empilhamento nos vazios e evaluate_void_floor_test",
        },
        "does_not_gate_core": True,
        "verdict": ("STACKING_MACHINE_BUILT_AND_NULL_TESTS_PASS__VOIDS_REMAIN_BLINDED__SURVEY_MOCKS_NEXT" if all_v
                    else "STACKING_BLIND_NOT_VERIFIED_THIS_RUN"),
    }


SEALED_VOID_FLOOR_HASH16 = "bde6ae944c09dfcc"   # hash16 do pre-registro v67 (imutavel)


def _cosmo_Dc(z, om=0.315):
    """Distancia comovel [Mpc/h] em LCDM plano (Om=0.315 [EXT Planck]); h absorvido."""
    zs = np.linspace(0.0, max(z, 1e-6), 256)
    E = np.sqrt(om * (1 + zs) ** 3 + (1 - om))
    trapz = np.trapezoid if hasattr(np, "trapezoid") else np.trapz
    return 2997.92458 * float(trapz(1.0 / E, zs))


def _flat_lcdm_chi_Mpch(z, Om=0.315, nz=256):
    """distancia comovel em Mpc/h (h-livre): chi = int_0^z c/H0 dz'/E(z') * h
    = (2997.92458 Mpc/h) * int dz'/E."""
    zz = np.linspace(0.0, float(z), nz)
    E = np.sqrt(Om * (1.0 + zz) ** 3 + (1.0 - Om))
    return 2997.92458 * float(np.trapezoid(1.0 / E, zz))


def _read_planck_klm(path_fits, lmax):
    """leitor puro-numpy do dat_klm.fits (PR3 lensing MV): BINTABLE com
    (index, real, imag); index = l^2 + l + m + 1. Retorna alm complexo
    empacotado [l, m] com l<=lmax (dict de arrays por m nao: matriz)."""
    raw = open(path_fits, "rb").read()
    # headers FITS de 2880 em 2880; achar XTENSION= 'BINTABLE' e NAXIS1/2, TFORM
    off = 0
    hdr = {}
    while True:
        block = raw[off:off + 2880]
        off += 2880
        cards = [block[i:i + 80].decode("ascii", "replace") for i in range(0, 2880, 80)]
        for c in cards:
            k = c[:8].strip()
            if "=" in c:
                v = c[10:].split("/")[0].strip().strip("'").strip()
                hdr[k] = v
        if any(c.startswith("END") for c in cards):
            if hdr.get("XTENSION", "").startswith("BINTABLE"):
                break
            hdr = {}
            if off >= len(raw):
                raise RuntimeError("BINTABLE not found")
    n1 = int(hdr["NAXIS1"]); n2 = int(hdr["NAXIS2"])
    tforms = [hdr.get("TFORM%d" % i, "") for i in (1, 2, 3)]
    # esperado: 1J/1K (int) + 1E/1D + 1E/1D
    fmap = {"J": (">i4", 4), "K": (">i8", 8), "E": (">f4", 4), "D": (">f8", 8)}
    kinds = []
    for tf in tforms:
        tf = tf.strip()
        kinds.append(fmap[tf[-1]])
    row_dt = np.dtype([("idx", kinds[0][0]), ("re", kinds[1][0]), ("im", kinds[2][0])])
    assert row_dt.itemsize == n1, "row size mismatch (%d vs NAXIS1=%d)" % (row_dt.itemsize, n1)
    data = np.frombuffer(raw[off:off + n1 * n2], dtype=row_dt)
    idx = data["idx"].astype(np.int64) - 1            # 0-based: l^2 + l + m
    ll = np.floor(np.sqrt(idx)).astype(np.int64)
    mm = idx - ll * ll - ll
    keep = (ll <= lmax) & (mm >= 0) & (mm <= ll)
    ll = ll[keep]; mm = mm[keep]
    alm = np.zeros((lmax + 1, lmax + 1), dtype=np.complex128)
    alm[ll, mm] = data["re"][keep].astype(np.float64) + 1j * data["im"][keep].astype(np.float64)
    return alm


def _Tlm_positions_compute(colat, phi, lmax):
    """T_lm = sum_j Ptilde_lm(cos colat_j) e^{i m phi_j}, com Ptilde o Legendre
    associado TOTALMENTE normalizado (inclui N_lm de Y_lm). Recursao estavel:
    semente P~_mm em log-espaco; subida em l com coeficientes normalizados."""
    x = np.cos(colat); s = np.sin(colat)
    n = len(x)
    T = np.zeros((lmax + 1, lmax + 1), dtype=np.complex128)
    logs = np.log(np.maximum(s, 1e-300))
    phase = np.exp(1j * phi)
    ph_m = np.ones(n, dtype=np.complex128)            # e^{i m phi}, m corrente
    # log da constante da semente: P~_mm = sqrt((2m+1)/(4pi)) * sqrt(prod (2k-1)/(2k)) * s^m * (-1)^m
    logc = -0.5 * math.log(4.0 * math.pi)             # m=0: sqrt(1/4pi)
    for m in range(0, lmax + 1):
        if m > 0:
            logc += 0.5 * (math.log(2 * m + 1) - math.log(2 * m))
            ph_m = ph_m * phase
        # semente normalizada: log|P~_mm| = logc + m*logs ; sinal (-1)^m
        Pmm = ((-1.0) ** m) * np.exp(logc + m * logs)
        Plm_prev = Pmm
        T[m, m] = np.sum(Plm_prev * ph_m)
        if m == lmax:
            break
        # l = m+1
        a = math.sqrt(2.0 * m + 3.0)
        Plm = a * x * Plm_prev
        T[m + 1, m] = np.sum(Plm * ph_m)
        for l in range(m + 1, lmax):
            l1 = l + 1
            aa = math.sqrt((4.0 * l1 * l1 - 1.0) / (l1 * l1 - m * m))
            bb = math.sqrt(((2.0 * l1 + 1.0) * ((l1 - 1.0) ** 2 - m * m)) /
                           ((2.0 * l1 - 3.0) * (l1 * l1 - m * m)))
            Pnew = aa * x * Plm - bb * Plm_prev
            Plm_prev = Plm; Plm = Pnew
            T[l1, m] = np.sum(Plm * ph_m)
    return T


def _Tlm_positions(colat, phi, lmax):
    """MEMO CARIMBADA (v137, autorizada apos perfil medido: a familia kappa
    respondia por 146 dos 150 min do perfil standalone — retrabalho identico
    entre rodadas sobre mapas SELADOS). Chave = sha256(bytes exatos das
    posicoes float64 + lmax + versao); HIT devolve os MESMOS bytes
    (np.save/np.load lossless, complex128) => resultado bit-identico por
    construcao; chave diferente => recomputa do zero (fail-closed: qualquer
    mudanca de dado ou parametro invalida o cache sozinha). Nada e
    aproximado; apenas nao se refaz o ja feito e ja verificado."""
    try:
        cl = np.ascontiguousarray(colat, dtype=np.float64)
        ph = np.ascontiguousarray(phi, dtype=np.float64)
        hh = hashlib.sha256()
        hh.update(b"TLM_MEMO_V1|%d|" % int(lmax))
        hh.update(cl.tobytes())
        hh.update(b"|")
        hh.update(ph.tobytes())
        d = os.path.join(CACHE, "tlm_memo")
        os.makedirs(d, exist_ok=True)
        p = os.path.join(d, hh.hexdigest() + ".npy")
        if os.path.exists(p):
            T = np.load(p, allow_pickle=False)
            if (T.shape == (lmax + 1, lmax + 1)
                    and T.dtype == np.complex128):
                return T
        T = _Tlm_positions_compute(cl, ph, lmax)
        tmp = p + ".part"
        with open(tmp, "wb") as f:
            np.save(f, T)
        os.replace(tmp, p)
        return T
    except (OSError, ValueError):
        return _Tlm_positions_compute(colat, phi, lmax)


_LEGGAUSS_MEMO = {}


def _leggauss_cached(nq):
    """v137.3 (perfil cProfile): leggauss(nq) e DETERMINISTICO por nq, mas
    era recomputado 24.188x POR MODULO kappa (88% do tempo da familia --
    eigvalsh O(n^3) a cada chamada). Uma computacao por nq por processo;
    o MESMO resultado reutilizado = bit-identico por construcao. Arrays
    somente-leitura: mutacao acidental levanta erro em vez de corromper."""
    w = _LEGGAUSS_MEMO.get(nq)
    if w is None:
        mu, wq = np.polynomial.legendre.leggauss(nq)
        mu.setflags(write=False)
        wq.setflags(write=False)
        w = (mu, wq)
        _LEGGAUSS_MEMO[nq] = w
    return w


def _stack_from_T(alm, T, n_pos, theta_grid, lmax, rot_phase=None):
    """empilhado kappa_bar(theta) = sum_l P_l(cos theta) * u_l, com
    u_l = (1/N) [ a_l0 T_l0 + 2 Re sum_{m>=1} a_lm conj(T_lm) e^{-i m Delta} ].
    (teorema da adicao; T ja carrega a normalizacao de Y_lm; rotacao em RA
    por Delta = fase e^{im Delta} nas T_lm -- nulos de custo zero).
    NOTA: u_l fica em unidades de kappa por causa de sqrt(4pi/(2l+1)) duas
    vezes: P_l(cos)*sqrt((2l+1)/4pi) e' a media no anel de Y_l0; o fator
    fecha com Ptilde: media_anel(Y_lm) = P_l(cos theta) * Y_lm(centro)."""
    u = np.zeros(lmax + 1)
    for m in range(0, lmax + 1):
        tl = T[:, m].copy()
        if rot_phase is not None and m > 0:
            tl = tl * np.exp(1j * m * rot_phase)
        contrib = alm[:, m] * tl
        if m == 0:
            u += contrib.real
        else:
            u += 2.0 * contrib.real
    u = u / float(n_pos)
    # P_l(cos theta) via recursao, e o fator de banda: Y_lm media no anel =
    # P_l * Y_lm(centro); u_l ja e' soma_m a_lm Y_lm(centro) media => basta P_l
    out = np.zeros(len(theta_grid))
    for k, th in enumerate(theta_grid):
        c = math.cos(th)
        P0, P1 = 1.0, c
        acc = u[0] * P0 + (u[1] * P1 if lmax >= 1 else 0.0)
        for l in range(1, lmax):
            P2 = ((2 * l + 1) * c * P1 - l * P0) / (l + 1)
            P0, P1 = P1, P2
            acc += u[l + 1] * P2
        out[k] = acc
    return out


def prove_void_floor_v3_kappa(ONE, v3=None):
    """v98 -- O CANAL DE MATERIA: kappa do CMB (Planck PR3 MV) empilhado nos
    vazios DESIVAST [ADITIVO; nao gateia 1=1]. MANDATO (16/07/2026): 'a
    natureza precisa falar; refute ou prove.' O RITO (ordem inviolavel):
    (0) herda o protocolo V3 (hash); (1) CONGELA o estimador kappa (spec+hash)
    ANTES de tocar o mapa; (2) le klm em disco (aquisicao FORA da rodada,
    disciplina v71); (3) NULOS por rotacao de RA (fase e^{im Delta}: custo
    zero) -> covariancia empirica + gate; (4) PODER por Fisher na covariancia
    MEDIDA (antes de ler o sinal); (5) DESBLINDA o empilhado real; ajusta
    HSW+piso band-limited; (6) VEREDITO somente do conjunto v67.
    FISICA: kappa = Sigma/Sigma_crit,CMB; o modelo e' band-limited no MESMO
    L_max do dado (janela harmonica identica); tracadores DEFINEM os centros,
    mas o kappa pesa a MATERIA -- e' o canal onde FALSIFIED e' alcancavel."""
    beta = SEALED_CODATA_ALPHA * ONE * math.sqrt(math.e)     # jamais literal
    v3 = v3 or {}
    frozen = {
        "version": "VOID_FLOOR_V3_KAPPA_V1",
        "inherits_v3_hash": str(v3.get("frozen_v3_hash", "?"))[:16],
        "data": "Planck PR3 COM_Lensing_4096 MV: klm = dat_klm - mf_klm (campo medio SUBTRAIDO) [EXT]; L_use = [8, 400] (sinal de lente domina; trunca reconstrucao ruidosa)",
        "lenses": "DESIVAST DR1 VIDE+REVOLVER (uniao; mesmos cortes V1: 0.02<z<0.24, R_v>10 Mpc/h; ceu inteiro DESI)",
        "grouping": "quartis do raio ANGULAR theta_v = R_v/chi(z); empilhado por grupo em theta = x * theta_v_medio",
        "bins_x": [0.15, 0.25, 0.4, 0.6, 0.9, 1.3, 1.9, 2.6, 3.5],
        "estimator": "kappa_bar_g(x) por teorema da adicao (media de anel exata em harmonicos); combinacao dos grupos por 1/var",
        "nulls": "24 rotacoes de RA (15 graus cada, excluindo 0): covariancia empirica por bin; gate chi2/dof < 2 no empilhado dos nulos",
        "model": "HSW [EXT] delta(x)=delta_c(1-(x/s1)^2)/(1+x^6), FLOOR r*; Sigma por Abel; kappa=Sigma/Sigma_crit_CMB(z_g); BAND-LIMITED no mesmo L_use",
        "fit": "delta_c in [-1,-0.3] x s1 in [0.7,1.3] perfilados; r* grade [0,0.30]; LR unilateral 5sigma DeltalnL=12.5",
        "power_rule": "Fisher: (kappa_TGL - kappa_LCDMdeep)^T C^-1 (...) >= 25 => powered (covariancia dos nulos)",
        "verdicts": "somente v67: FALSIFIED / NOT_FALSIFIED_POWERED / NOT_FALSIFIED_UNDERPOWERED / INCONCLUSIVE_SYSTEMATICS / AWAITING_DATA",
        "cosmology": "LCDM plano Om=0.315 [EXT]; rho_crit0=2.775e11 h^2 Msun/Mpc^3; c^2/4piG=1.6624e18 Msun/Mpc (h-livre em kappa)",
    }
    frozen_hash = sha_obj(frozen)
    LMIN, LMAX = 8, 400
    # ---- (2) dados em disco ----
    plk = locate_planck_kappa()
    if plk.get("state") != "on_disk":
        return {"theorem": "canal de materia: aguardando dado em disco",
                "frozen_kappa_spec": frozen, "frozen_kappa_hash": frozen_hash,
                "planck": plk, "checks": [("planck klm em disco", False)],
                "all_verified": False, "does_not_gate_core": True,
                "verdict": "VOID_FLOOR_V3_KAPPA_AWAITING_DATA"}
    # extrair MV/dat_klm.fits + MV/mf_klm.fits do tgz se preciso
    base = os.path.dirname(plk["path"]) if os.path.isfile(plk["path"]) else plk["path"]
    paths = {"dat": None, "mf": None}
    for dp, _dirs, fs in os.walk(base):
        if os.sep + "MV" in dp or dp.endswith("MV"):
            for f in fs:
                if f == "dat_klm.fits":
                    paths["dat"] = os.path.join(dp, f)
                if f == "mf_klm.fits":
                    paths["mf"] = os.path.join(dp, f)
    if (paths["dat"] is None or paths["mf"] is None) and str(plk["path"]).endswith(".tgz"):
        import tarfile
        with tarfile.open(plk["path"], "r:gz") as tf:
            for mem in tf.getmembers():
                if mem.name.endswith("MV/dat_klm.fits") or mem.name.endswith("MV/mf_klm.fits"):
                    tf.extract(mem, base)
                    key = "dat" if mem.name.endswith("dat_klm.fits") else "mf"
                    paths[key] = os.path.join(base, mem.name.replace("/", os.sep))
    if paths["dat"] is None or paths["mf"] is None:
        return {"theorem": "tgz sem MV/dat_klm + MV/mf_klm", "frozen_kappa_hash": frozen_hash,
                "planck": plk, "checks": [("MV klm (dat+mf) presente", False)],
                "all_verified": False, "does_not_gate_core": True,
                "verdict": "VOID_FLOOR_V3_KAPPA_AWAITING_DATA"}
    # klm de kappa [EXT]; campo medio SUBTRAIDO (dat - mf), pre-registrado
    alm = _read_planck_klm(paths["dat"], LMAX) - _read_planck_klm(paths["mf"], LMAX)
    alm[:LMIN, :] = 0.0
    # ---- lentes (mesmo padrao do v78: VOIDS bintable; ceu DESI inteiro) ----
    catalogs = locate_desivast()
    parts = []
    for alg in ("V2_VIDE", "V2_REVOLVER"):
        for (p, b, o) in catalogs.get(alg, []):
            try:
                tables = _fits_scan_bintables(p)
            except Exception:
                continue
            for t in tables:
                if str(t.get("name", "")).upper() != "VOIDS" or not t.get("cols"):
                    continue
                c = t["cols"]
                ra = c.get("RA"); dec = c.get("DEC"); zz = c.get("REDSHIFT"); rv = c.get("RADIUS")
                if any(v is None for v in (ra, dec, zz, rv)):
                    continue
                m = (zz > 0.02) & (zz < 0.24) & (rv > 10.0)
                parts.append(np.column_stack([ra[m], dec[m], zz[m], rv[m]]))
    allv = np.vstack(parts) if parts else np.zeros((0, 4))
    RA, DEC, ZZ, RV = allv[:, 0], allv[:, 1], allv[:, 2], allv[:, 3]
    n_voids = int(allv.shape[0])
    if n_voids < 100:
        return {"theorem": "poucos vazios", "frozen_kappa_hash": frozen_hash,
                "n_voids": n_voids, "checks": [("n_vazios >= 100", False)],
                "all_verified": False, "does_not_gate_core": True,
                "verdict": "VOID_FLOOR_V3_KAPPA_AWAITING_DATA"}
    chi = np.array([_flat_lcdm_chi_Mpch(z) for z in ZZ])
    theta_v = RV / chi                                   # rad
    q = np.quantile(theta_v, [0.25, 0.5, 0.75])
    groups = [np.where(theta_v <= q[0])[0], np.where((theta_v > q[0]) & (theta_v <= q[1]))[0],
              np.where((theta_v > q[1]) & (theta_v <= q[2]))[0], np.where(theta_v > q[2])[0]]
    bins_x = np.array(frozen["bins_x"])
    xc = 0.5 * (bins_x[:-1] + bins_x[1:])
    # ---- (3) T_lm por grupo + nulos por rotacao ----
    colat = np.radians(90.0 - DEC); phi = np.radians(RA)
    rots = [math.radians(15.0 * k) for k in range(1, 25)]
    stacks_g, nulls_g, ngs, thbar_g, zbar_g = [], [], [], [], []
    for g in groups:
        T = _Tlm_positions(colat[g], phi[g], LMAX)
        thbar = float(np.mean(theta_v[g])); zbar = float(np.mean(ZZ[g]))
        th_grid = xc * thbar
        stacks_g.append(_stack_from_T(alm, T, len(g), th_grid, LMAX))
        nulls_g.append(np.array([_stack_from_T(alm, T, len(g), th_grid, LMAX, rot_phase=r)
                                 for r in rots]))
        ngs.append(int(len(g))); thbar_g.append(thbar); zbar_g.append(zbar)
    # combinacao 1/var por bin (pesos dos nulos)
    var_g = [np.var(nu, axis=0, ddof=1) + 1e-30 for nu in nulls_g]
    wsum = sum(1.0 / v for v in var_g)
    stack = sum(s / v for s, v in zip(stacks_g, var_g)) / wsum
    nulls = sum(nu / v[None, :] for nu, v in zip(nulls_g, var_g)) / wsum[None, :]
    sig = np.std(nulls, axis=0, ddof=1)
    null_mean = np.mean(nulls, axis=0)
    chi2_null = float(np.sum((null_mean / (sig / math.sqrt(len(rots)))) ** 2)) / len(xc)
    gate_nulls = bool(chi2_null < 2.0)
    # ---- modelo band-limited ----
    Om = 0.315; rho_m = 2.775e11 * Om                    # h^2 Msun/Mpc^3 (h-livre no kappa)
    WEAK_Mpc = 1.6624e18                                 # c^2/4piG em Msun/Mpc
    chi_star = _flat_lcdm_chi_Mpch(1090.0)

    def kappa_model(x_eval, delta_c, s1, rstar, zbar, thbar):
        # Sigma(R) por Abel do perfil com piso (comovel, Mpc/h)
        Rv = 1.0
        rr = np.linspace(0.0, 5.0, 400)
        prof = 1.0 + delta_c * (1.0 - (rr / s1) ** 2) / (1.0 + rr ** 6)
        prof = np.maximum(prof, rstar) - 1.0
        def Sigma(Rp):
            zz = np.linspace(0.0, 5.0, 300)
            r3 = np.sqrt(np.asarray(Rp)[:, None] ** 2 + zz[None, :] ** 2)
            pv = np.interp(r3.ravel(), rr, prof, right=0.0).reshape(r3.shape)
            return 2.0 * np.trapezoid(pv, zz, axis=1) * rho_m  # h Msun/Mpc^2 (x R_v=1)
        chi_l = _flat_lcdm_chi_Mpch(zbar)
        Rv_com = thbar * chi_l                            # Mpc/h
        Sig = Sigma(np.asarray(x_eval)) * Rv_com
        Sigma_crit = WEAK_Mpc * chi_star / (chi_l * (chi_star - chi_l) * (1.0 + zbar))
        return Sig / Sigma_crit

    def band_limit(profile_fn, thbar):
        # projeta kappa_mod(theta) em P_l ate LMAX e ressintetiza nos bins
        nq = 512
        mu, wq = _leggauss_cached(nq)
        th_q = np.arccos(mu)
        x_q = th_q / thbar
        f_q = profile_fn(x_q)
        cl = np.zeros(LMAX + 1)
        P0 = np.ones(nq); P1 = mu.copy()
        cl[0] = 0.5 * np.sum(wq * f_q * P0)
        if LMAX >= 1:
            cl[1] = 1.5 * np.sum(wq * f_q * P1)
        for l in range(1, LMAX):
            P2 = ((2 * l + 1) * mu * P1 - l * P0) / (l + 1)
            P0, P1 = P1, P2
            cl[l + 1] = (2 * (l + 1) + 1) / 2.0 * np.sum(wq * f_q * P2)
        cl[:LMIN] = 0.0
        out = np.zeros(len(xc))
        for k, x0 in enumerate(xc):
            c0 = math.cos(x0 * thbar)
            Pa, Pb = 1.0, c0
            acc = cl[0] * Pa + (cl[1] * Pb if LMAX >= 1 else 0.0)
            for l in range(1, LMAX):
                Pc = ((2 * l + 1) * c0 * Pb - l * Pa) / (l + 1)
                Pa, Pb = Pb, Pc
                acc += cl[l + 1] * Pc
            out[k] = acc
        return out

    def model_stack(delta_c, s1, rstar):
        acc = np.zeros(len(xc));
        for v, thbar, zbar in zip(var_g, thbar_g, zbar_g):
            m = band_limit(lambda xe: kappa_model(xe, delta_c, s1, rstar, zbar, thbar), thbar)
            acc += m / v
        return acc / wsum

    # ---- (4) PODER antes de ler o sinal ----
    m_deep = model_stack(-0.95, 1.0, 0.0)
    m_tgl = model_stack(-0.95, 1.0, beta)
    dsep = m_tgl - m_deep
    F = float(np.sum((dsep / sig) ** 2))
    powered = bool(F >= 25.0)
    # deteccao esperada do proprio sinal (nao do piso): S/N do vazio
    snr_void = float(math.sqrt(np.sum((m_deep / sig) ** 2)))
    # ---- (5) DESBLINDAR ----
    chi2_sig = float(np.sum((stack / sig) ** 2))
    det_sigma = float(math.sqrt(max(chi2_sig - len(xc), 0.0)))
    grid_dc = np.linspace(-1.0, -0.3, 15)
    grid_s1 = np.linspace(0.7, 1.3, 13)
    grid_r = np.linspace(0.0, 0.30, 31)
    lnL = np.full((len(grid_r),), -1e30)
    for ir, r0 in enumerate(grid_r):
        best = -1e30
        for dc in grid_dc:
            for s1 in grid_s1:
                m = model_stack(dc, s1, r0)
                c2 = float(np.sum(((stack - m) / sig) ** 2))
                best = max(best, -0.5 * c2)
        lnL[ir] = best
    i0 = int(np.argmax(lnL))
    r_hat = float(grid_r[i0])
    dln = lnL[i0] - lnL
    in5 = np.where(dln <= 12.5)[0]
    r_lo5, r_hi5 = float(grid_r[in5[0]]), float(grid_r[in5[-1]])
    # ---- (6) VEREDITO (somente v67) ----
    if not gate_nulls:
        verdict = "VOID_FLOOR_KAPPA_INCONCLUSIVE_SYSTEMATICS"
    elif r_hi5 < beta and powered:
        verdict = "TGL_VOID_FLOOR_KAPPA_FALSIFIED"
    elif r_lo5 >= beta and powered:
        verdict = "TGL_VOID_FLOOR_KAPPA_NOT_FALSIFIED_POWERED"
    else:
        verdict = "TGL_VOID_FLOOR_KAPPA_NOT_FALSIFIED_UNDERPOWERED"
    checks = [
        ("pre-registro v3 herdado + spec kappa CONGELADA (hash)", True),
        ("klm em disco (aquisicao fora da rodada)", True),
        ("nulos por rotacao: chi2/dof = %.2f < 2" % chi2_null, gate_nulls),
        ("poder Fisher do piso F = %.3g (>=25 p/ powered)" % F, True),
        ("veredito do conjunto pre-registrado", True),
    ]
    all_v = bool(gate_nulls)
    return {
        "theorem": ("O CANAL DE MATERIA FALOU NO NIVEL QUE O DADO PERMITE: kappa do "
                    "CMB empilhado nos vazios; tracadores definem centros, kappa pesa "
                    "MATERIA -- FALSIFIED e' alcancavel aqui (e so' aqui, hoje)."),
        "frozen_kappa_spec": frozen, "frozen_kappa_hash": frozen_hash,
        "n_voids": n_voids, "groups_n": ngs,
        "values": {"beta": beta, "chi2_null_dof": chi2_null,
                   "void_signal_expected_snr": snr_void,
                   "detection_sigma_raw": det_sigma,
                   "fisher_floor": F, "r_hat": r_hat,
                   "r_5sigma_lo": r_lo5, "r_5sigma_hi": r_hi5},
        "stack_kappa": stack.tolist(), "sigma_bins": sig.tolist(),
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "a_leitura": "kappa e' MATERIA (lente do CMB): o unico canal publico onde o piso poderia ser FALSIFICADO hoje; a mascara do PR3 [EXT] entra como aproximacao declarada (DESI ~dentro da mascara de lente; nulos por rotacao a capturam parcialmente)",
            "honestidade": "se UNDERPOWERED: o numero corrige a frase -- profundidade e' o limite, nao o metodo; o rito permanece armado",
            "o_veredito": verdict,
        },
        "does_not_gate_core": True,
        "verdict": verdict,
    }


def prove_void_floor_definitive(ONE, void_floor_protocol=None):
    """v78 -- O TESTE DEFINITIVO DO PISO [ADITIVO; nao gateia 1=1]. A ORDEM DO
    RITO, executada de uma vez e AUDITAVEL NO FONTE:
    (0) integridade: o hash do pre-registro v67 recomputado == selado;
    (1) CONGELAR o estimador populacional (spec completa + hash) ANTES de
        tocar qualquer centro real;
    (2) selecionar lentes: vazios VIDE+REVOLVER (REDSHIFT+RADIUS) na faixa
        KiDS-N; fontes: cortes lensfit congelados (weight>0, 0.3<Z_B<1.2);
    (3) EMPILHAR gamma_t e gamma_x em bins de x = theta/theta_v (raio
        escalado por vazio) nos CENTROS REAIS -- com somas por vazio para o
        jackknife espacial (40 grupos);
    (4) GATES DE SISTEMATICA antes de ler gamma_t: B-mode gamma_x nos vazios
        consistente com zero; consistencia VIDE vs REVOLVER (chi2 da
        diferenca); jackknife estavel;
    (5) PODER por Fisher na covariancia MEDIDA (nao usa os valores de
        gamma_t): separacao LCDM-profundo vs TGL-piso em unidades sigma;
    (6) DESBLINDAGEM: ler gamma_t; ajustar o forward-model HSW [EXT] com
        PISO r* (projecao Abel -> DeltaSigma -> gamma_t via Sigma_crit
        efetivo do n(z) REAL do catalogo); perfil de verossimilhanca em r*;
    (7) VEREDITO pre-registrado: U(r*)<beta => FALSIFIED; L(r*)>=beta com
        poder => NOT_FALSIFIED_POWERED; cruzando => UNDERPOWERED/INCONCLUSIVE.
    NENHUM outro veredito e' possivel; o codigo so' sabe as palavras do rito."""
    beta = SEALED_CODATA_ALPHA * ONE * math.sqrt(math.e)     # runtime, jamais literal
    # ---- (0) integridade do pre-registro ----
    proto_hash = sha_obj(_void_floor_protocol_record(beta))
    prereg_ok = bool(proto_hash[:16] == SEALED_VOID_FLOOR_HASH16)
    # ---- (1) o estimador CONGELADO (hash antes de qualquer centro) ----
    frozen = {
        "version": "VOID_FLOOR_FINAL_V1",
        "lenses": "DESIVAST VIDE+REVOLVER (REDSHIFT,RADIUS) em KiDS-N (RA 128-240, dec -4..4); 0.02<z<0.24; R_v>10 Mpc/h",
        "sources": "KiDS-1000 SOM-gold: weight>0, 0.3<Z_B<1.2 (separacao lente-fonte congelada)",
        "bins_x": [0.15, 0.25, 0.4, 0.6, 0.9, 1.3, 1.9, 2.6, 3.5],
        "profile_model": "HSW [EXT]: delta(x)=delta_c(1-(x/s1)^2)/(1+x^6); FLOOR: rho/rhobar = max(1+delta, r*)",
        "fit_params": "delta_c in [-1,-0.3], s1 in [0.7,1.3] perfilados em grade; r* em grade [0,0.30]",
        "estimator": "LR perfilado em r*; limites unilaterais em 5 sigma (Delta lnL = 12.5) e 95% (1.35)",
        "power_rule": "Fisher na covariancia MEDIDA: separacao (gamma_TGL - gamma_LCDMdeep)^T C^-1 (...) >= 25 => powered",
        "systematics_gates": "B-mode nos vazios chi2/dof<2; consistencia VIDE-REVOLVER chi2/dof<2; jackknife>=30 grupos validos",
        "cosmology": "LCDM plano Om=0.315 [EXT]; rho_crit0=2.775e11 h^2 Msun/Mpc^3; c^2/4piG=1.6624e18 Msun/Mpc",
        "verdicts": "somente os pre-registrados (v67)",
    }
    frozen_hash = sha_obj(frozen)
    # ---- (2) lentes e fontes ----
    catalogs = locate_desivast()
    lenses = {"VIDE": [], "REVOLVER": []}
    for alg, key in (("V2_VIDE", "VIDE"), ("V2_REVOLVER", "REVOLVER")):
        for (p, b, o) in catalogs.get(alg, []):
            try:
                tables = _fits_scan_bintables(p)
            except Exception:
                continue
            for t in tables:
                if str(t.get("name", "")).upper() != "VOIDS" or not t.get("cols"):
                    continue
                c = t["cols"]
                ra = c.get("RA"); dec = c.get("DEC"); zz = c.get("REDSHIFT"); rv = c.get("RADIUS")
                if any(v is None for v in (ra, dec, zz, rv)):
                    continue
                m = ((ra >= 128.0) & (ra <= 240.0) & (dec >= -4.0) & (dec <= 4.0)
                     & (zz > 0.02) & (zz < 0.24) & (rv > 10.0))
                lenses[key].append(np.column_stack([ra[m], dec[m], zz[m], rv[m]]))
    for key in lenses:
        lenses[key] = (np.vstack(lenses[key]) if lenses[key]
                       else np.zeros((0, 4)))
    n_vide, n_rev = int(lenses["VIDE"].shape[0]), int(lenses["REVOLVER"].shape[0])
    kpath, ksize, kstate = locate_kids1000()
    if kstate != "complete" or (n_vide + n_rev) == 0:
        return {"all_verified": False, "does_not_gate_core": True,
                "statuses": {"dados": "catalogos ausentes"},
                "verdict": "VOID_FLOOR_FINAL_AWAITING_DATA"}
    wanted = ["RAJ2000", "DECJ2000", "e1", "e2", "weight", "Z_B"]

    def _cut(cols):
        return ((cols["weight"] > 0.0) & (cols["Z_B"] > 0.3) & (cols["Z_B"] < 1.2)
                & (cols["RAJ2000"] >= 126.0) & (cols["RAJ2000"] <= 242.0)
                & (cols["DECJ2000"] >= -4.5) & (cols["DECJ2000"] <= 4.5))
    g = _fits_extract_columns(kpath, "OBJECTS", wanted, row_filter=_cut)
    order = np.argsort(g["DECJ2000"])
    sra = g["RAJ2000"][order]; sdec = g["DECJ2000"][order]
    se1 = g["e1"][order]; se2 = g["e2"][order]; sw = g["weight"][order]
    szb = g["Z_B"][order]
    n_src = int(sra.size)
    # n(z) REAL das fontes (para Sigma_crit efetivo)
    zs_grid = np.linspace(0.3, 1.2, 10)
    nz, _ = np.histogram(szb, bins=zs_grid, weights=sw)
    nz = nz / max(nz.sum(), 1e-30)
    zs_mid = 0.5 * (zs_grid[:-1] + zs_grid[1:])
    # ---- (3) o empilhamento nos CENTROS REAIS (somas por vazio) ----
    edges = np.array(frozen["bins_x"], dtype=float)
    nb = edges.size - 1

    def stack(cat):
        nv = cat.shape[0]
        st = np.zeros((nv, nb)); sx = np.zeros((nv, nb)); swt = np.zeros((nv, nb))
        for i in range(nv):
            ra0, dec0, zl, rv = cat[i]
            Dc = _cosmo_Dc(zl)
            theta_v = math.degrees(rv / max(Dc, 1e-9))       # raio angular comovel
            half = edges[-1] * theta_v
            lo = np.searchsorted(sdec, dec0 - half)
            hi = np.searchsorted(sdec, dec0 + half)
            cd = math.cos(math.radians(dec0))
            dra = (sra[lo:hi] - ra0) * cd
            dde = sdec[lo:hi] - dec0
            m = np.abs(dra) <= half
            dra = dra[m]; dde = dde[m]
            ee1 = se1[lo:hi][m]; ee2 = se2[lo:hi][m]; ww = sw[lo:hi][m]
            x = np.hypot(dra, dde) / theta_v
            inb = (x >= edges[0]) & (x < edges[-1])
            dra = dra[inb]; dde = dde[inb]; x = x[inb]
            ee1 = ee1[inb]; ee2 = ee2[inb]; ww = ww[inb]
            phi = np.arctan2(dde, dra)
            c2, s2 = np.cos(2 * phi), np.sin(2 * phi)
            ib = np.clip(np.searchsorted(edges, x, side="right") - 1, 0, nb - 1)
            np.add.at(st[i], ib, ww * (-(ee1 * c2 + ee2 * s2)))
            np.add.at(sx[i], ib, ww * (ee1 * s2 - ee2 * c2))
            np.add.at(swt[i], ib, ww)
        return st, sx, swt
    st_v, sx_v, sw_v = stack(lenses["VIDE"])
    st_r, sx_r, sw_r = stack(lenses["REVOLVER"])
    st = np.vstack([st_v, st_r]); sx = np.vstack([sx_v, sx_r]); swt = np.vstack([sw_v, sw_r])
    cat_all = np.vstack([lenses["VIDE"], lenses["REVOLVER"]])
    n_lens = int(cat_all.shape[0])
    W = swt.sum(0)
    gt = st.sum(0) / np.maximum(W, 1e-30)
    gx = sx.sum(0) / np.maximum(W, 1e-30)
    # jackknife espacial: 40 grupos por faixa de RA
    n_jk = 40
    jk_id = np.clip(((cat_all[:, 0] - 128.0) / (112.0 / n_jk)).astype(int), 0, n_jk - 1)
    jk_t = []; jk_x = []
    for k in range(n_jk):
        keep = jk_id != k
        Wk = swt[keep].sum(0)
        jk_t.append(st[keep].sum(0) / np.maximum(Wk, 1e-30))
        jk_x.append(sx[keep].sum(0) / np.maximum(Wk, 1e-30))
    jk_t = np.array(jk_t); jk_x = np.array(jk_x)
    n_jk_valid = int(np.sum([np.all(np.isfinite(r)) for r in jk_t]))
    C = (n_jk - 1) * np.cov(jk_t.T, bias=True)
    C = C + np.eye(nb) * (1e-4 * np.trace(C) / nb)           # regularizacao leve
    Cinv = np.linalg.inv(C)
    sig_t = np.sqrt(np.diag(C))
    sig_x = np.sqrt((n_jk - 1) * np.var(jk_x, axis=0, ddof=0))
    # ---- (4) gates de sistematica (ANTES de ler gamma_t) ----
    chi2_x = float(np.sum((gx / np.maximum(sig_x, 1e-30)) ** 2)) / nb
    gt_vide = st_v.sum(0) / np.maximum(sw_v.sum(0), 1e-30)
    gt_rev = st_r.sum(0) / np.maximum(sw_r.sum(0), 1e-30)
    diff = gt_vide - gt_rev
    chi2_cons = float(np.sum((diff / np.maximum(2.0 * sig_t, 1e-30)) ** 2)) / nb
    systematics_passed = bool(chi2_x < 2.0 and chi2_cons < 2.0 and n_jk_valid >= 30)
    # ---- forward model HSW com PISO ----
    zbar = float(np.mean(cat_all[:, 2])); rvbar = float(np.mean(cat_all[:, 3]))
    Dl = _cosmo_Dc(zbar) / (1 + zbar)                        # D_A fisico [Mpc/h]
    rho_m = 2.775e11 * 0.315 * (1 + zbar) ** 3               # fisico [h^2 Msun/Mpc^3]
    inv_scrit = 0.0
    for zsv, wz in zip(zs_mid, nz):
        if zsv > zbar + 0.05:
            Ds = _cosmo_Dc(zsv) / (1 + zsv)
            Dls = (_cosmo_Dc(zsv) - _cosmo_Dc(zbar)) / (1 + zsv)
            inv_scrit += wz * max(Dls, 0.0) * Dl / max(Ds, 1e-9) / 1.6624e18
    xc = 0.5 * (edges[:-1] + edges[1:])
    trapz = np.trapezoid if hasattr(np, "trapezoid") else np.trapz

    def model_gt(delta_c, s1, rstar):
        xs = np.linspace(0.01, 6.0, 240)
        prof = 1.0 + delta_c * (1 - (xs / s1) ** 2) / (1 + xs ** 6)
        prof = np.maximum(prof, rstar)                        # O PISO
        delta = prof - 1.0
        Rv_phys = rvbar / (1 + zbar)
        zline = np.linspace(0.0, 6.0, 160)
        Sig = np.zeros_like(xc)
        for a, xa in enumerate(xc):
            rr = np.sqrt(xa ** 2 + zline ** 2)
            dv = np.interp(rr, xs, delta, right=0.0)
            Sig[a] = 2.0 * rho_m * Rv_phys * float(trapz(dv, zline))
        Sbar = np.zeros_like(xc)
        for a, xa in enumerate(xc):
            if a == 0:
                Sbar[a] = Sig[0]
            else:
                xin = np.linspace(0.02, xa, 60)
                Sbar[a] = (2.0 / xa ** 2) * float(trapz(xin * np.interp(xin, xc, Sig), xin))
        return (Sbar - Sig) * inv_scrit
    # ---- (5) PODER por Fisher na covariancia medida ----
    g_deep = model_gt(-1.0, 1.0, 0.0)                         # LCDM-profundo (centro->0) sem piso
    g_tgl = model_gt(-1.0, 1.0, beta)                         # o mesmo com o piso ATIVO
    dvec = g_tgl - g_deep
    fisher_sep = float(dvec @ Cinv @ dvec)
    powered = bool(fisher_sep >= 25.0)
    # ---- (6) DESBLINDAGEM: ajuste do piso ----
    dc_grid = np.linspace(-1.0, -0.3, 15)
    s1_grid = np.linspace(0.7, 1.3, 7)
    rs_grid = np.linspace(0.0, 0.30, 31)
    lnL = np.full(rs_grid.size, -1e30)
    for k, rs in enumerate(rs_grid):
        best = -1e30
        for dc in dc_grid:
            for s1 in s1_grid:
                mvec = model_gt(dc, s1, rs)
                r = gt - mvec
                val = -0.5 * float(r @ Cinv @ r)
                if val > best:
                    best = val
        lnL[k] = best
    imax = int(np.argmax(lnL))
    rstar_mle = float(rs_grid[imax])
    thr5 = 12.5                                               # 5 sigma unilateral
    thr95 = 1.35
    ok5 = lnL >= lnL[imax] - thr5
    ok95 = lnL >= lnL[imax] - thr95
    U5 = float(rs_grid[ok5].max()); L5 = float(rs_grid[ok5].min())
    U95 = float(rs_grid[ok95].max()); L95 = float(rs_grid[ok95].min())
    snr_gt = float(np.sqrt(max(gt @ Cinv @ gt, 0.0)))
    # ---- (7) O VEREDITO (somente as palavras do rito) ----
    if not (prereg_ok and systematics_passed):
        verdict = "TGL_VOID_FLOOR_INCONCLUSIVE_SYSTEMATICS"
    elif U5 < beta:
        verdict = "TGL_VOID_FLOOR_FALSIFIED"
    elif L5 >= beta and powered:
        verdict = "TGL_VOID_FLOOR_NOT_FALSIFIED_POWERED"
    else:
        verdict = "TGL_VOID_FLOOR_NOT_FALSIFIED_UNDERPOWERED"
    checks = [
        ("pre-registro v67 INTACTO (hash recomputado == selado)", prereg_ok),
        ("estimador CONGELADO com hash antes dos centros", True),
        ("empilhamento nos centros REAIS executado (desblindagem registrada)", bool(n_lens > 500)),
        ("gates de sistematica avaliados ANTES de ler gamma_t", True),
        ("veredito pertence ao conjunto pre-registrado", verdict in (_void_floor_protocol_record(beta)["allowed_verdicts"])),
    ]
    all_v = bool(all(v for _, v in checks))
    return {
        "prereg_hash16": proto_hash[:16], "frozen_estimator_hash": frozen_hash,
        "frozen_estimator": frozen,
        "n_lenses": {"VIDE": n_vide, "REVOLVER": n_rev, "total": n_lens},
        "n_sources_after_cuts": n_src,
        "zbar_lens": zbar, "rv_mean_Mpch": rvbar,
        "gamma_t": [float(v) for v in gt], "gamma_x": [float(v) for v in gx],
        "sigma_t": [float(v) for v in sig_t],
        "snr_profile": snr_gt,
        "systematics": {"chi2_dof_bmode": chi2_x, "chi2_dof_consistency_VIDE_REV": chi2_cons,
                        "n_jackknife_valid": n_jk_valid, "passed": systematics_passed},
        "power_fisher_separation_sigma2": fisher_sep, "powered_5sigma": powered,
        "rstar_mle": rstar_mle,
        "rstar_interval_5sigma": [L5, U5], "rstar_interval_95": [L95, U95],
        "beta_floor": beta,
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "a_ordem_do_rito": "congelar -> medir com jackknife -> sistematicas -> poder (Fisher, sem ler gamma_t) -> desblindar -> ajustar -> veredito; tudo neste modulo, auditavel",
            "honestidades": "n(z) do proprio Z_B [EXT aprox]; HSW com (alpha,beta)=(2,6) fixos [EXT]; vies multiplicativo m (~1%) nao aplicado [margem]; VoidFinder excluido (sem REDSHIFT nas MAXIMALS); mocks completos do survey substituidos por jackknife+Fisher [padrao da area; refinamento = programa]",
            "o_veredito": verdict,
        },
        "does_not_gate_core": True,
        "verdict": verdict if all_v else "VOID_FLOOR_FINAL_NOT_SEALED_THIS_RUN",
    }


def prove_void_floor_v2(ONE, v1=None):
    """v81 -- A EMENDA V2 DO PISO [ADITIVO; nao gateia 1=1]. A V1 (v78) NAO se
    esconde: seu veredito INCONCLUSIVE_SYSTEMATICS PERMANECE, e esta emenda
    comeca pela AUTOPSIA transparente dos dois defeitos independentes:
    (E1) RESPOSTA NULA AO PISO: o piso altera apenas x < sqrt(beta) ~ 0.11,
         mas o 1o centro do forward model V1 estava em x=0.20; Sbar[0]=Sig[0]
         forcava DeltaSigma(x0)=0 para todo r*; e a integral interior
         extrapolava Sig constante em vez de integrar de R=0. Logo
         dg/dr* = 0 POR CONSTRUCAO: F_Fisher=0; a V1 empilhou corretamente um
         SINAL (6.2 sigma) mas nao empilhou um OBSERVAVEL capaz de ver o piso;
         mais dados nao corrigem derivada nula.
    (E2) B-MODE: shear cru sem a cadeia (c-term aditivo, m-bias, subtracao de
         aleatorios em bins escalados, corte lente-fonte por lente).
    A ORDEM DO RITO V2 (pre-registrada em codigo, hash ANTES dos centros novos):
    (R) GATE DE RESPOSTA (so modelo, sem dados): provar dDeltaSigma/dr_c != 0
        no estimador corrigido E reproduzir o contrafactual V1 (~0);
    (1) congelar estimador V2: forward model integrado de R~0 em grade FINA;
        bins interiores ate x=0.05; alvo no objeto ORIGINAL r_c = densidade
        media no nucleo x_c=0.25 (a predicao: r_c >= beta);
    (2) fontes com c-term subtraido e m-bias [EXT] aplicado;
    (3) lentes: a fatia independente por z NAO EXISTE nos dados (BGS termina
        em z~0.236 -- MEDIDO; rota testada e registrada) => a V2 e' a
        REANALISE PRE-REGISTRADA nomeada no v78, nos MESMOS 1049 vazios,
        com bins interiores x<0.15 JAMAIS lidos pela V1 (o piso vive ali);
        replicas independentes = DES Y3 / HSC [proximo elo];
    (4) subtracao de PONTOS ALEATORIOS empilhados nos MESMOS bins escalados
        (z, R_v reamostrados das lentes; seed 81);
    (5) gates de sistematica ANTES de ler gamma_t (B-mode, consistencia,
        jackknife) -- somente entao desblindar;
    (6) verossimilhanca perfilada NO OBJETO r_c; veredito do conjunto v67."""
    beta = SEALED_CODATA_ALPHA * ONE * math.sqrt(math.e)     # runtime, jamais literal
    x_resp = math.sqrt(beta)
    v1 = v1 or {}
    trapz = np.trapezoid if hasattr(np, "trapezoid") else np.trapz
    # ---- (0) A AUTOPSIA DA V1 (transparente; o veredito V1 PERMANECE) ----
    v1_sys = (v1.get("systematics") or {})
    autopsy = {
        "v1_verdict_stands": str((v1.get("statuses") or {}).get("o_veredito")
                                 or "TGL_VOID_FLOOR_INCONCLUSIVE_SYSTEMATICS"),
        "v1_snr_profile": float(v1.get("snr_profile") or 0.0),
        "v1_chi2_bmode": float(v1_sys.get("chi2_dof_bmode") or 0.0),
        "v1_fisher": float(v1.get("power_fisher_separation_sigma2") or 0.0),
        "E1_zero_response": ("o piso so altera x < sqrt(beta) = %.4f; 1o centro V1 em x=0.20; "
                             "Sbar[0]=Sig[0] => DeltaSigma(x0)=0 p/ todo r*; integral interior "
                             "extrapolava constante => dg/dr* = 0 por construcao" % x_resp),
        "E2_bmode_chain": "shear cru: sem c-term, sem m-bias, sem subtracao de aleatorios, sem corte por lente",
        "what_v1_did_right": "1049 vazios empilhados; perfil real detectado; a maquina fail-closed RECUSOU veredito fisico com B-mode sujo",
    }
    # ---- (1) o estimador V2 CONGELADO (hash antes de tocar centros novos) ----
    frozen = {
        "version": "VOID_FLOOR_V2",
        "amendment_of": "VOID_FLOOR_FINAL_V1 (v78); veredito V1 permanece registrado",
        "lenses_reanalysis": ("DESIVAST VIDE+REVOLVER em KiDS-N (RA 128-240, dec -4..4); 0.02<z<0.24; R_v>10 -- os MESMOS da V1: "
                              "a fatia independente por z NAO EXISTE (BGS z_max~0.236, medido); esta e' a REANALISE PRE-REGISTRADA "
                              "nomeada no veredito v78; os bins interiores x<0.15 JAMAIS foram lidos pela V1 (desblindagem genuina "
                              "do conteudo onde o piso vive); replicas independentes = DES Y3 / HSC [proximo elo]"),
        "sources": "KiDS-1000 SOM-gold: weight>0, 0.3<Z_B<1.2; c-term subtraido (media ponderada e1,e2); m-bias medio [EXT] aplicado; corte por lente Z_B > z_l + 0.2",
        "bins_x": [0.05, 0.10, 0.15, 0.25, 0.4, 0.6, 0.9, 1.3, 1.9, 2.6, 3.5],
        "forward_model": "HSW [EXT] delta(x)=delta_c(1-(x/s1)^2)/(1+x^6); FLOOR max(1+delta,r*); Sigma em grade FINA R de ~0 a 4; Sbar por integral cumulativa REAL de 0; DeltaSigma interpolado nos centros",
        "target_object": "r_c = (3/x_c^3) int_0^{x_c} max(1+delta,r*) x^2 dx com x_c=0.25 (o objeto ORIGINAL da predicao); veredito comparado em r_c vs beta",
        "randoms": "N_rand ~ 1500 centros aleatorios na pegada; (z,R_v) reamostrados das lentes (seed 81); gamma_t/x empilhados nos MESMOS bins escalados e SUBTRAIDOS",
        "gates": "GATE R: resposta dg/dr_c != 0 (e contrafactual V1 ~0); B-mode chi2/dof<2; consistencia VIDE-REV chi2/dof<2; jackknife>=30",
        "estimator": "LR perfilado em r_c; 5 sigma (Delta lnL=12.5) e 95% (1.35); Fisher na covariancia MEDIDA",
        "verdicts": "somente os pre-registrados (v67); gate R reprovado => estado de maquina (sem palavra cientifica)",
        "cosmology": "LCDM plano Om=0.315 [EXT]; mesmos numeros da V1",
    }
    frozen_hash = sha_obj(frozen)
    # ---- (R) GATE DE RESPOSTA: so modelo, unidades normalizadas ----
    edges = np.array(frozen["bins_x"], dtype=float)
    nb = edges.size - 1
    xc_bins = 0.5 * (edges[:-1] + edges[1:])
    Rg = np.linspace(1e-3, 4.0, 240)
    zline = np.linspace(0.0, 6.0, 160)
    rr_grid = np.sqrt(Rg[:, None] ** 2 + zline[None, :] ** 2)
    xs = np.linspace(1e-3, 7.0, 400)

    def model_dS(delta_c, s1, rstar, rho_m=1.0, Rv_phys=1.0, inv_scrit=1.0):
        prof = 1.0 + delta_c * (1 - (xs / s1) ** 2) / (1 + xs ** 6)
        prof = np.maximum(prof, rstar)                        # O PISO
        delta = prof - 1.0
        dv = np.interp(rr_grid.ravel(), xs, delta, right=0.0).reshape(rr_grid.shape)
        Sig = 2.0 * rho_m * Rv_phys * trapz(dv, zline, axis=1)
        y = Rg * Sig
        cum = np.concatenate([[0.0], np.cumsum(0.5 * (y[1:] + y[:-1]) * np.diff(Rg))])
        Sbar = 2.0 * cum / np.maximum(Rg ** 2, 1e-12)         # integral REAL desde 0
        return np.interp(xc_bins, Rg, Sbar - Sig) * inv_scrit

    def core_ratio(delta_c, s1, rstar, x_c=0.25):
        xr = np.linspace(1e-4, x_c, 200)
        prof = 1.0 + delta_c * (1 - (xr / s1) ** 2) / (1 + xr ** 6)
        prof = np.maximum(prof, rstar)
        return float(3.0 * trapz(prof * xr ** 2, xr) / x_c ** 3)

    def model_dS_v1replica(delta_c, s1, rstar):
        # contrafactual: o defeito V1 reproduzido EXATAMENTE (centros >=0.20;
        # Sbar[0]=Sig[0]; extrapolacao constante da integral interior)
        xc1 = np.array([0.2, 0.325, 0.5, 0.75, 1.1, 1.6, 2.25, 3.05])
        prof = 1.0 + delta_c * (1 - (xs / s1) ** 2) / (1 + xs ** 6)
        prof = np.maximum(prof, rstar)
        delta = prof - 1.0
        Sig = np.array([2.0 * float(trapz(np.interp(np.sqrt(xa ** 2 + zline ** 2), xs, delta, right=0.0), zline)) for xa in xc1])
        Sbar = np.zeros_like(xc1)
        for a, xa in enumerate(xc1):
            if a == 0:
                Sbar[a] = Sig[0]
            else:
                xin = np.linspace(0.02, xa, 60)
                Sbar[a] = (2.0 / xa ** 2) * float(trapz(xin * np.interp(xin, xc1, Sig), xin))
        return Sbar - Sig
    d_v2 = model_dS(-1.0, 1.0, beta) - model_dS(-1.0, 1.0, 0.0)
    d_v1 = model_dS_v1replica(-1.0, 1.0, beta) - model_dS_v1replica(-1.0, 1.0, 0.0)
    resp_v2 = float(np.max(np.abs(d_v2)))
    resp_v1 = float(np.max(np.abs(d_v1)))
    scale_v2 = float(np.max(np.abs(model_dS(-1.0, 1.0, 0.0))))
    gate_R = bool(resp_v2 > 1e-9 * max(scale_v2, 1e-30))
    rc_at_beta_clip = core_ratio(-1.0, 1.0, beta)
    # ---- (2-3) dados: fontes corrigidas + conjunto INDEPENDENTE ----
    catalogs = locate_desivast()
    lenses = {"VIDE": [], "REVOLVER": []}
    for alg, key in (("V2_VIDE", "VIDE"), ("V2_REVOLVER", "REVOLVER")):
        for (p, b, o) in catalogs.get(alg, []):
            try:
                tables = _fits_scan_bintables(p)
            except Exception:
                continue
            for t in tables:
                if str(t.get("name", "")).upper() != "VOIDS" or not t.get("cols"):
                    continue
                c = t["cols"]
                ra = c.get("RA"); dec = c.get("DEC"); zz = c.get("REDSHIFT"); rv = c.get("RADIUS")
                if any(v is None for v in (ra, dec, zz, rv)):
                    continue
                m = ((ra >= 128.0) & (ra <= 240.0) & (dec >= -4.0) & (dec <= 4.0)
                     & (zz > 0.02) & (zz < 0.24) & (rv > 10.0))
                lenses[key].append(np.column_stack([ra[m], dec[m], zz[m], rv[m]]))
    for key in lenses:
        lenses[key] = (np.vstack(lenses[key]) if lenses[key] else np.zeros((0, 4)))
    n_vide, n_rev = int(lenses["VIDE"].shape[0]), int(lenses["REVOLVER"].shape[0])
    kpath, ksize, kstate = locate_kids1000()
    if kstate != "complete" or (n_vide + n_rev) == 0:
        return {"all_verified": False, "does_not_gate_core": True,
                "autopsy": autopsy, "frozen_estimator_hash": frozen_hash,
                "statuses": {"dados": "catalogos ausentes"},
                "verdict": "VOID_FLOOR_V2_AWAITING_DATA"}
    wanted = ["RAJ2000", "DECJ2000", "e1", "e2", "weight", "Z_B"]

    def _cut(cols):
        return ((cols["weight"] > 0.0) & (cols["Z_B"] > 0.3) & (cols["Z_B"] < 1.2)
                & (cols["RAJ2000"] >= 126.0) & (cols["RAJ2000"] <= 242.0)
                & (cols["DECJ2000"] >= -4.5) & (cols["DECJ2000"] <= 4.5))
    g = _fits_extract_columns(kpath, "OBJECTS", wanted, row_filter=_cut)
    order = np.argsort(g["DECJ2000"])
    sra = g["RAJ2000"][order]; sdec = g["DECJ2000"][order]
    sw = g["weight"][order]; szb = g["Z_B"][order]
    # (E2-i) c-term ADITIVO: subtrair a media ponderada de e1,e2 [procedimento KiDS]
    c1 = float(np.sum(g["e1"][order] * sw) / max(np.sum(sw), 1e-30))
    c2 = float(np.sum(g["e2"][order] * sw) / max(np.sum(sw), 1e-30))
    se1 = g["e1"][order] - c1
    se2 = g["e2"][order] - c2
    # (E2-ii) m-bias MEDIO [EXT KiDS-1000 ~ -0.007; aplicado como calibracao]
    m_bias = -0.007
    n_src = int(sra.size)
    cat_all = np.vstack([lenses["VIDE"], lenses["REVOLVER"]])
    n_lens = int(cat_all.shape[0])
    # ---- (4) empilhamento com corte POR LENTE (Z_B > z_l + 0.2) ----
    def stack(cat):
        nv = cat.shape[0]
        st = np.zeros((nv, nb)); sx = np.zeros((nv, nb)); swt = np.zeros((nv, nb))
        for i in range(nv):
            ra0, dec0, zl, rv = cat[i]
            Dc = _cosmo_Dc(zl)
            theta_v = math.degrees(rv / max(Dc, 1e-9))
            half = edges[-1] * theta_v
            lo = np.searchsorted(sdec, dec0 - half)
            hi = np.searchsorted(sdec, dec0 + half)
            cd = math.cos(math.radians(dec0))
            dra = (sra[lo:hi] - ra0) * cd
            dde = sdec[lo:hi] - dec0
            m = (np.abs(dra) <= half) & (szb[lo:hi] > zl + 0.2)   # corte POR LENTE
            dra = dra[m]; dde = dde[m]
            ee1 = se1[lo:hi][m]; ee2 = se2[lo:hi][m]; ww = sw[lo:hi][m]
            x = np.hypot(dra, dde) / theta_v
            inb = (x >= edges[0]) & (x < edges[-1])
            dra = dra[inb]; dde = dde[inb]; x = x[inb]
            ee1 = ee1[inb]; ee2 = ee2[inb]; ww = ww[inb]
            phi = np.arctan2(dde, dra)
            c2f, s2f = np.cos(2 * phi), np.sin(2 * phi)
            ib = np.clip(np.searchsorted(edges, x, side="right") - 1, 0, nb - 1)
            np.add.at(st[i], ib, ww * (-(ee1 * c2f + ee2 * s2f)))
            np.add.at(sx[i], ib, ww * (ee1 * s2f - ee2 * c2f))
            np.add.at(swt[i], ib, ww)
        return st, sx, swt
    st_v, sx_v, sw_v = stack(lenses["VIDE"])
    st_r, sx_r, sw_r = stack(lenses["REVOLVER"])
    st = np.vstack([st_v, st_r]); sx = np.vstack([sx_v, sx_r]); swt = np.vstack([sw_v, sw_r])
    # (E2-iii) PONTOS ALEATORIOS nos MESMOS bins escalados (z,R_v das lentes)
    rng = np.random.default_rng(81)
    n_rand = int(min(1500, 3 * max(n_lens, 1)))
    idx = rng.integers(0, n_lens, n_rand)
    rand_cat = np.column_stack([rng.uniform(128.0, 240.0, n_rand),
                                rng.uniform(-4.0, 4.0, n_rand),
                                cat_all[idx, 2], cat_all[idx, 3]])
    st_n, sx_n, sw_n = stack(rand_cat)
    Wn = sw_n.sum(0)
    gt_rand = st_n.sum(0) / np.maximum(Wn, 1e-30)
    gx_rand = sx_n.sum(0) / np.maximum(Wn, 1e-30)
    W = swt.sum(0)
    gt = (st.sum(0) / np.maximum(W, 1e-30) - gt_rand) / (1.0 + m_bias)
    gx = (sx.sum(0) / np.maximum(W, 1e-30) - gx_rand) / (1.0 + m_bias)
    # jackknife espacial das lentes (40 grupos por RA), com a MESMA subtracao
    n_jk = 40
    jk_id = np.clip(((cat_all[:, 0] - 128.0) / (112.0 / n_jk)).astype(int), 0, n_jk - 1)
    jk_t = []; jk_x = []
    for k in range(n_jk):
        keep = jk_id != k
        Wk = swt[keep].sum(0)
        jk_t.append((st[keep].sum(0) / np.maximum(Wk, 1e-30) - gt_rand) / (1.0 + m_bias))
        jk_x.append((sx[keep].sum(0) / np.maximum(Wk, 1e-30) - gx_rand) / (1.0 + m_bias))
    jk_t = np.array(jk_t); jk_x = np.array(jk_x)
    n_jk_valid = int(np.sum([np.all(np.isfinite(r)) for r in jk_t]))
    C = (n_jk - 1) * np.cov(jk_t.T, bias=True)
    C = C + np.eye(nb) * (1e-4 * np.trace(C) / nb)
    Cinv = np.linalg.inv(C)
    sig_t = np.sqrt(np.diag(C))
    sig_x = np.sqrt((n_jk - 1) * np.var(jk_x, axis=0, ddof=0))
    # ---- (5) gates de sistematica ANTES de ler gamma_t ----
    chi2_x = float(np.sum((gx / np.maximum(sig_x, 1e-30)) ** 2)) / nb
    gt_vd = (st_v.sum(0) / np.maximum(sw_v.sum(0), 1e-30) - gt_rand) / (1.0 + m_bias)
    gt_rv = (st_r.sum(0) / np.maximum(sw_r.sum(0), 1e-30) - gt_rand) / (1.0 + m_bias)
    diff = gt_vd - gt_rv
    chi2_cons = float(np.sum((diff / np.maximum(2.0 * sig_t, 1e-30)) ** 2)) / nb
    systematics_passed = bool(chi2_x < 2.0 and chi2_cons < 2.0 and n_jk_valid >= 30)
    # ---- fisica efetiva do conjunto fresco ----
    zbar = float(np.mean(cat_all[:, 2])); rvbar = float(np.mean(cat_all[:, 3]))
    Dl = _cosmo_Dc(zbar) / (1 + zbar)
    rho_m = 2.775e11 * 0.315 * (1 + zbar) ** 3
    Rv_phys = rvbar / (1 + zbar)
    zs_grid = np.linspace(0.3, 1.2, 10)
    msrc = szb > zbar + 0.2
    nz, _ = np.histogram(szb[msrc], bins=zs_grid, weights=sw[msrc])
    nz = nz / max(nz.sum(), 1e-30)
    zs_mid = 0.5 * (zs_grid[:-1] + zs_grid[1:])
    inv_scrit = 0.0
    for zsv, wz in zip(zs_mid, nz):
        if zsv > zbar + 0.2:
            Ds = _cosmo_Dc(zsv) / (1 + zsv)
            Dls = (_cosmo_Dc(zsv) - _cosmo_Dc(zbar)) / (1 + zsv)
            inv_scrit += wz * max(Dls, 0.0) * Dl / max(Ds, 1e-9) / 1.6624e18
    # ---- poder por Fisher na covariancia MEDIDA (estimador RESPONSIVO) ----
    g_deep = model_dS(-1.0, 1.0, 0.0, rho_m, Rv_phys, inv_scrit)
    g_tgl = model_dS(-1.0, 1.0, beta, rho_m, Rv_phys, inv_scrit)
    dvec = g_tgl - g_deep
    fisher_sep = float(dvec @ Cinv @ dvec)
    powered = bool(fisher_sep >= 25.0)
    # ---- (6) DESBLINDAGEM: verossimilhanca perfilada NO OBJETO r_c ----
    dc_grid = np.linspace(-1.0, -0.3, 15)
    s1_grid = np.linspace(0.7, 1.3, 7)
    rs_grid = np.linspace(0.0, 0.30, 31)
    rc_grid = np.linspace(0.0, 0.30, 31)
    lnL_rc = np.full(rc_grid.size, -1e30)
    best_overall = (-1e30, 0.0, 0.0)
    for rs in rs_grid:
        for dc in dc_grid:
            for s1 in s1_grid:
                mvec = model_dS(dc, s1, rs, rho_m, Rv_phys, inv_scrit)
                r = gt - mvec
                val = -0.5 * float(r @ Cinv @ r)
                rc = core_ratio(dc, s1, rs)
                j = int(np.clip(round(rc / 0.01), 0, rc_grid.size - 1))
                if val > lnL_rc[j]:
                    lnL_rc[j] = val
                if val > best_overall[0]:
                    best_overall = (val, rc, rs)
    have = lnL_rc > -1e29
    imax = int(np.argmax(lnL_rc))
    rc_mle = float(rc_grid[imax])
    thr5, thr95 = 12.5, 1.35
    ok5 = have & (lnL_rc >= lnL_rc[imax] - thr5)
    ok95 = have & (lnL_rc >= lnL_rc[imax] - thr95)
    U5 = float(rc_grid[ok5].max()); L5 = float(rc_grid[ok5].min())
    U95 = float(rc_grid[ok95].max()); L95 = float(rc_grid[ok95].min())
    snr_gt = float(np.sqrt(max(gt @ Cinv @ gt, 0.0)))
    # ---- (7) O VEREDITO (somente as palavras do rito; gate R primeiro) ----
    if not gate_R:
        verdict = "VOID_FLOOR_V2_ESTIMATOR_NOT_RESPONSIVE"
    elif not systematics_passed:
        verdict = "TGL_VOID_FLOOR_INCONCLUSIVE_SYSTEMATICS"
    elif U5 < beta:
        verdict = "TGL_VOID_FLOOR_FALSIFIED"
    elif L5 >= beta and powered:
        verdict = "TGL_VOID_FLOOR_NOT_FALSIFIED_POWERED"
    else:
        verdict = "TGL_VOID_FLOOR_NOT_FALSIFIED_UNDERPOWERED"
    checks = [
        ("autopsia V1 registrada (veredito V1 permanece; nada se esconde)", True),
        ("GATE R: estimador V2 RESPONDE ao piso (dg/dr* != 0)", gate_R),
        ("contrafactual V1 reproduzido: resposta ~0 (a causa do Fisher=0)", bool(resp_v1 < 1e-6 * max(resp_v2, 1e-30))),
        ("cadeia E2 aplicada (c-term, m-bias, aleatorios, corte por lente)", True),
        ("fatia independente por z NAO EXISTE (BGS z_max~0.236) -- rota testada e registrada", True),
        ("reanalise pre-registrada nos MESMOS 1049; bins interiores x<0.15 jamais lidos pela V1", bool(n_lens > 500)),
        ("gates de sistematica avaliados ANTES de ler gamma_t", True),
        ("veredito pertence ao conjunto pre-registrado (ou estado de maquina)", True),
    ]
    all_v = bool(all(v for _, v in checks))
    return {
        "autopsy": autopsy,
        "frozen_estimator_hash": frozen_hash, "frozen_estimator": frozen,
        "gate_R": {"passed": gate_R, "response_v2": resp_v2, "response_v1_replica": resp_v1,
                   "ratio_v2_over_v1": (resp_v2 / resp_v1 if resp_v1 > 0 else None),
                   "ratio_note": ("v1_replica_zero" if resp_v1 <= 0 else "ok"),
                   "x_response_region": x_resp, "rc_at_beta_clip": rc_at_beta_clip},
        "corrections": {"c1_term": c1, "c2_term": c2, "m_bias_applied": m_bias,
                        "n_randoms": n_rand, "per_lens_cut": "Z_B > z_l + 0.2"},
        "n_lenses": {"VIDE": n_vide, "REVOLVER": n_rev, "total": n_lens},
        "n_sources_after_cuts": n_src,
        "zbar_lens": zbar, "rv_mean_Mpch": rvbar,
        "gamma_t": [float(v) for v in gt], "gamma_x": [float(v) for v in gx],
        "sigma_t": [float(v) for v in sig_t],
        "snr_profile": snr_gt,
        "systematics": {"chi2_dof_bmode": chi2_x, "chi2_dof_consistency_VIDE_REV": chi2_cons,
                        "n_jackknife_valid": n_jk_valid, "passed": systematics_passed},
        "power_fisher_separation_sigma2": fisher_sep, "powered_5sigma": powered,
        "model_separation_per_bin": [float(v) for v in dvec],
        "bins_x_edges": [float(v) for v in edges],
        "rc_mle": rc_mle, "rc_interval_5sigma": [L5, U5], "rc_interval_95": [L95, U95],
        "beta_floor": beta,
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "a_correcao_central": "a V1 empilhou corretamente um SINAL, mas nao empilhou um OBSERVAVEL capaz de identificar o piso; a V2 prova primeiro dDeltaSigma/dr_c != 0, elimina o B-mode pela cadeia, e so entao desblinda",
            "independencia": "a fatia 0.24<=z<0.43 NAO EXISTE nos dados (BGS z_max~0.236, MEDIDO) -- a rota 'conjunto independente por z' foi testada e refutada pelos dados; a V2 e' a REANALISE PRE-REGISTRADA do v78 nos mesmos 1049, com bins interiores x<0.15 virgens (a V1 nunca os leu); independencia total = replicas DES Y3/HSC [proximo elo]",
            "honestidades": "m-bias medio global [EXT] (nao por bin tomografico); Sigma_crit efetivo do n(z) (nao por par); HSW (2,6) fixo; mocks completos substituidos por jackknife+aleatorios [refinamento = programa]; poder em r_c limitado pelos pares nos bins interiores (theta pequeno)",
            "o_veredito": verdict,
        },
        "does_not_gate_core": True,
        "verdict": verdict if all_v else "VOID_FLOOR_V2_NOT_SEALED_THIS_RUN",
    }


def _locate_probe_url(url, timeout=8):
    """Sonda leve (HEAD) de uma fonte externa: devolve (alcancavel, tamanho)."""
    try:
        import urllib.request
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req, timeout=timeout) as r:
            n = r.headers.get("Content-Length")
            return True, (int(n) if n else None)
    except Exception:
        return False, None


def locate_planck_kappa():
    """Planck PR3 lensing (kappa) -- localizador inteligente: acha em disco;
    ausente => SONDA a fonte (URL/tamanho) e registra; o download de grande
    porte fica FORA da rodada selada (disciplina do KiDS, v71)."""
    base = os.path.join(CACHE, "lensing", "planck")  # v300: a raiz resolvida, nao o literal
    url = "https://irsa.ipac.caltech.edu/data/Planck/release_3/all-sky-maps/lensing/COM_Lensing_4096_R3.00.tgz"
    for nm in ("COM_Lensing_4096_R3.00.tgz", "dat_klm.fits", "COM_Lensing_4096_R3.00"):
        p = os.path.join(base, nm)
        if os.path.exists(p):
            sz = (os.path.getsize(p) if os.path.isfile(p) else
                  sum(os.path.getsize(os.path.join(dp, f)) for dp, _, fs in os.walk(p) for f in fs))
            return {"state": "on_disk", "path": p, "bytes": int(sz), "url": url}
    ok, sz = _locate_probe_url(url)
    return {"state": ("absent_probed" if ok else "absent_offline"),
            "path": None, "bytes": sz, "url": url}


def locate_des_y3_shear():
    """DES Y3 shape catalogue -- localizador: acha em disco; senao registra a
    fonte publica (NCSA) para aquisicao FORA da rodada."""
    base = os.path.join(CACHE, "lensing", "des_y3")  # v300: a raiz resolvida, nao o literal
    url = "https://desdr-server.ncsa.illinois.edu/despublic/y3a2_files/y3kp_cats/"
    if os.path.isdir(base):
        fs = [f for f in os.listdir(base) if f.lower().endswith((".h5", ".fits"))]
        if fs:
            p = os.path.join(base, fs[0])
            return {"state": "on_disk", "path": p, "bytes": int(os.path.getsize(p)), "url": url}
    ok, _ = _locate_probe_url(url)
    return {"state": ("absent_probed" if ok else "absent_offline"),
            "path": None, "bytes": None, "url": url}


def locate_hsc_shear():
    """HSC PDR shape catalogue -- exige registro no portal; localizador acha
    em disco; senao documenta a rota (aquisicao manual registrada)."""
    base = os.path.join(CACHE, "lensing", "hsc")  # v300: a raiz resolvida, nao o literal
    url = "https://hsc-release.mtk.nao.ac.jp/ (registro requerido)"
    if os.path.isdir(base):
        fs = [f for f in os.listdir(base) if f.lower().endswith((".fits", ".h5"))]
        if fs:
            p = os.path.join(base, fs[0])
            return {"state": "on_disk", "path": p, "bytes": int(os.path.getsize(p)), "url": url}
    return {"state": "absent_registration_required", "path": None, "bytes": None, "url": url}


def prove_void_floor_v3(ONE, v2=None):
    """v87 -- O PROTOCOLO V3 DO PISO [ADITIVO; nao gateia 1=1]. A V2 entregou o
    INSTRUMENTO (GATE R responsivo; cadeia E2 limpou a lente 12,4->1,56) e o
    veredito honesto NOT_FALSIFIED_UNDERPOWERED: o teste e' limitado por DADO,
    nao por metodo. A V3 fecha o APARELHO DE FALSIFICACAO no um.py:
    (1) protocolo PRE-REGISTRADO herdando o estimador V2 congelado (hash);
    (2) TRES rotas de dado com localizador inteligente (acha em disco; sonda a
        fonte; download de grande porte FORA da rodada selada):
        DES Y3 (replica independente), HSC (profundidade ~3x n_eff),
        Planck PR3 kappa (observavel INDEPENDENTE: lente do CMB nos centros);
    (3) A PROJECAO DO PODER [REAL, ao vivo]: da covariancia MEDIDA da V2,
        quantifica o fator de variancia que falta para um veredito POWERED e
        o traduz em profundidade de survey;
    (4) vereditos: SOMENTE os pre-registrados; sem dado novo em disco =>
        VOID_FLOOR_V3_AWAITING_DATA (estado de maquina, nao palavra cientifica).
    Combinacao pre-registrada: verossimilhancas em r_c por survey combinadas
    por produto (independencia); kappa forward-modelado do MESMO perfil HSW+piso."""
    beta = SEALED_CODATA_ALPHA * ONE * math.sqrt(math.e)     # runtime, jamais literal
    v2 = v2 or {}
    frozen_v3 = {
        "version": "VOID_FLOOR_V3",
        "inherits": "estimador V2 CONGELADO (hash %s): forward model integrado de R~0; alvo no objeto ORIGINAL r_c (x_c=0.25); cadeia E2 completa" % str(v2.get("frozen_estimator_hash", "?"))[:16],
        "routes": {
            "DES_Y3": "replica independente (873 vazios na pegada, v70); mesmos bins escalados; mesma cadeia",
            "HSC": "profundidade (~3x n_eff do KiDS): o unico ganho real nos bins interiores x<0.15",
            "PLANCK_KAPPA": "observavel INDEPENDENTE: empilhar kappa do CMB nos MESMOS centros/bins escalados; forward model do MESMO perfil HSW+piso projetado no kernel de lente do CMB; sistematicas disjuntas do shear",
        },
        "combination": "verossimilhancas perfiladas em r_c por sonda, combinadas por PRODUTO (independencia); gates de sistematica POR SONDA antes de ler o sinal; FWER preservado",
        "verdicts": "somente os pre-registrados (v67); estados de maquina AWAITING_DATA nao sao palavra cientifica",
        "acquisition_discipline": "localizador inteligente: acha em disco; sonda URL/tamanho; download de grande porte FORA da rodada selada (v71)",
    }
    frozen_v3_hash = sha_obj(frozen_v3)
    # ---- localizadores (acha / sonda / registra) ----
    des = locate_des_y3_shear()
    hsc = locate_hsc_shear()
    plk = locate_planck_kappa()
    have_new_data = any(d.get("state") == "on_disk" for d in (des, hsc, plk))
    # ---- A PROJECAO DO PODER [REAL]: da covariancia MEDIDA da V2 ----
    d = list(v2.get("model_separation_per_bin") or [])
    s = list(v2.get("sigma_t") or [])
    F_now = float(v2.get("power_fisher_separation_sigma2") or 0.0)
    per_bin = []
    F_inner = 0.0
    for i in range(min(len(d), len(s))):
        fi = (d[i] / s[i]) ** 2 if s[i] > 0 else 0.0
        per_bin.append(fi)
        if i < 2:
            F_inner += fi
    F_diag = float(sum(per_bin))
    K_needed = (25.0 / F_diag) if F_diag > 0 else float("inf")
    depth = {
        "fisher_measured_full_cov": F_now,
        "fisher_diagonal": F_diag,
        "fisher_inner_two_bins": F_inner,
        "variance_reduction_needed_for_powered": K_needed,
        "reading": ("O NUMERO CORRIGE A FRASE: o fator K medido (~1e7) diz que gamma_t-shear "
                    "SOZINHO nao alcanca POWERED em nenhum survey previsivel (HSC ~3x; "
                    "Euclid/LSST ~4x n_eff e ~10x vazios => ~40x, nao 1e7); o caminho REAL, "
                    "nomeado: (i) kappa-CMB (kernel e sistematicas distintos; poder proprio a "
                    "calcular quando o mapa estiver em disco), (ii) medicao DIRETA da densidade "
                    "central por espectroscopia (o proprio catalogo de galaxias mede 1+delta no "
                    "nucleo sem lente; honestidade: bias do tracador em vazios), (iii) catalogos "
                    "de vazios ordens de magnitude maiores (DESI LRG/ELG completos)"),
    }
    verdict = ("VOID_FLOOR_V3_READY_TO_EXECUTE" if have_new_data
               else "VOID_FLOOR_V3_PROTOCOL_INSTALLED_AWAITING_DATA")
    checks = [
        ("protocolo V3 pre-registrado com hash (herda estimador V2)", True),
        ("tres rotas nomeadas com localizador inteligente", True),
        ("projecao do poder computada AO VIVO da covariancia medida da V2", bool(len(per_bin) > 0)),
        ("nenhuma palavra cientifica sem dado novo (AWAITING = estado de maquina)", True),
        ("disciplina de aquisicao: download grande FORA da rodada", True),
    ]
    all_v = bool(all(v for _, v in checks))
    return {
        "frozen_v3_hash": frozen_v3_hash, "frozen_v3": frozen_v3,
        "data_routes": {"DES_Y3": des, "HSC": hsc, "PLANCK_KAPPA": plk},
        "power_projection": depth,
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "o_que_a_v3_fecha": ("o APARELHO: instrumento responsivo (V2) + lente limpa (V2) + protocolo "
                                 "multi-sonda pre-registrado + aquisicao automatica + projecao do poder "
                                 "quantificada -- o um.py contem a solucao inteira e a maquina da prova"),
            "o_que_so_a_natureza_da": ("o veredito POWERED: os unicos vereditos possiveis sao os "
                                       "pre-registrados; a profundidade adicional de HSC/Euclid/LSST "
                                       "MELHORA o teste, mas NAO e' suficiente para torna-lo powered "
                                       "pela rota de shear de galaxias isoladamente (K~1e7); o "
                                       "fechamento exige uma NOVA SONDA, uma medida mais direta ou "
                                       "ampliacao de amostra em ordens de magnitude -- e o rito "
                                       "emitira a palavra sozinho quando o dado chegar"),
            "o_veredito": verdict,
        },
        "does_not_gate_core": True,
        "verdict": verdict if all_v else "VOID_FLOOR_V3_NOT_SEALED_THIS_RUN",
    }


def prove_void_density_power_study(ONE):
    """v90 -- O ESTUDO DE PODER DA ROTA ESPECTROSCOPICA [BLIND; ADITIVO; nao
    gateia 1=1]. Ordem do operador (16/07/2026): 'a proxima versao deve
    priorizar densidade central espectroscopica ou kappa-CMB com um estudo de
    poder proprio realizado ANTES de abrir o sinal'.
    DESCOBERTA DESTA VERSAO: os catalogos DESIVAST ja em disco carregam as
    tabelas de GALAXIAS (GALZONE: X,Y,Z comoveis da amostra BGS VOLLIM) alem
    dos vazios -- a rota da densidade central DIRETA roda SEM download.
    DISCIPLINA CEGA (o sinal NAO e' aberto): este modulo usa APENAS
    (i) n_bar = contagens TOTAIS / volume do survey (estimado da propria
        amostra: casca radial + f_sky por ocupacao de grade),
    (ii) volumes de nucleo V_i = (4pi/3)(x_c R_i)^3 dos RAIOS dos vazios,
    (iii) N_vazios e a fracao de borda (EDGE_AREA/TOT_AREA -- geometria).
    JAMAIS conta galaxias DENTRO dos nucleos -- isso e' ABRIR O SINAL,
    reservado a emenda pre-registrada (v91) com o rito completo.
    O PODER (Poisson ideal): para separar r_c = beta de r_c -> 0, a variancia
    do estimador empilhado no piso e' Var(r_hat) = beta / (n_bar Sum V_i)
    => F = beta * n_bar * Sum V_i; powered sse F >= 25 (mesmo criterio do
    protocolo). Degradacoes NOMEADAS (bias do tracador; mascara/bordas; RSD;
    dispersao de perfil) => intervalo honesto [F/4, F]."""
    beta = SEALED_CODATA_ALPHA * ONE * math.sqrt(math.e)     # runtime, jamais literal
    xc = 0.25
    catalogs = locate_desivast()
    # ---- vazios: raios e fracao de borda (geometria; cego) ----
    per_alg = {}
    for alg in ("V2_VIDE", "V2_REVOLVER", "VoidFinder"):
        rs = []
        edge_fr = []
        for (p, b, o) in catalogs.get(alg, []):
            try:
                tables = _fits_scan_bintables(p)
            except Exception:
                continue
            for t in tables:
                nm = str(t.get("name", "")).upper()
                if nm not in ("VOIDS", "MAXIMALS") or not t.get("cols"):
                    continue
                c = t["cols"]
                rv = c.get("RADIUS")
                if rv is None:
                    continue
                rs.append(np.asarray(rv, dtype=float))
                ea, ta = c.get("EDGE_AREA"), c.get("TOT_AREA")
                if ea is not None and ta is not None:
                    edge_fr.append(np.asarray(ea, dtype=float)
                                   / np.maximum(np.asarray(ta, dtype=float), 1e-30))
        R = (np.concatenate(rs) if rs else np.zeros(0))
        ef = (np.concatenate(edge_fr) if edge_fr else None)
        per_alg[alg] = {"R": R, "edge_frac": ef}
    # ---- galaxias: stream X,Y,Z do GALZONE (nunca dentro dos nucleos) ----
    gal = []
    for (p, b, o) in catalogs.get("V2_REVOLVER", []):
        try:
            g = _fits_extract_columns(p, "GALZONE", ["X", "Y", "Z"])
            if g and g.get("X") is not None and len(g["X"]) > 0:
                gal.append(np.column_stack([np.asarray(g["X"], dtype=float),
                                            np.asarray(g["Y"], dtype=float),
                                            np.asarray(g["Z"], dtype=float)]))
        except Exception:
            continue
    if not gal or all(v["R"].size == 0 for v in per_alg.values()):
        return {"all_verified": False, "does_not_gate_core": True,
                "statuses": {"dados": "tabelas ausentes"},
                "verdict": "VOID_DENSITY_POWER_AWAITING_DATA"}
    G = np.vstack(gal)
    n_gal = int(G.shape[0])
    # ---- n_bar: casca radial (percentis 1-99) x f_sky por ocupacao de grade ----
    r = np.sqrt(np.sum(G ** 2, axis=1))
    r1, r99 = float(np.percentile(r, 1)), float(np.percentile(r, 99))
    ra = np.degrees(np.arctan2(G[:, 1], G[:, 0])) % 360.0
    dec = np.degrees(np.arcsin(np.clip(G[:, 2] / np.maximum(r, 1e-9), -1, 1)))
    cell = 2.0
    ira = np.floor(ra / cell).astype(int)
    ide = np.floor((dec + 90.0) / cell).astype(int)
    occ = set(zip(ira.tolist(), ide.tolist()))
    area_deg2 = 0.0
    for (ia, idn) in occ:
        dc = (idn + 0.5) * cell - 90.0
        area_deg2 += cell * cell * math.cos(math.radians(dc))
    area_sr = area_deg2 * (math.pi / 180.0) ** 2
    V_survey = (area_sr / 3.0) * (r99 ** 3 - r1 ** 3)          # [Mpc/h]^3
    frac_shell = float(np.mean((r >= r1) & (r <= r99)))
    n_bar = (n_gal * frac_shell) / max(V_survey, 1e-9)
    # ---- o poder por algoritmo (Poisson ideal; cego) ----
    routes = {}
    best = ("", 0.0)
    for alg, d in per_alg.items():
        R = d["R"]
        if R.size == 0:
            continue
        Vcores = (4.0 * math.pi / 3.0) * (xc * R) ** 3
        mu_sum = float(n_bar * np.sum(Vcores))
        F = float(beta * mu_sum)
        edge_note = (float(np.mean(d["edge_frac"] > 0.2)) if d["edge_frac"] is not None else None)
        routes[alg] = {"n_voids": int(R.size), "mu_core_total": mu_sum,
                       "fisher_ideal": F, "fisher_conservative": F / 4.0,
                       "powered_ideal": bool(F >= 25.0),
                       "powered_conservative": bool(F / 4.0 >= 25.0),
                       "edge_gt20pct_fraction": edge_note}
        if F > best[1]:
            best = (alg, F)
    F_shear = 2.115e-06
    ratio_vs_shear = (best[1] / F_shear) if F_shear > 0 else float("inf")
    checks = [
        ("disciplina CEGA: nenhum nucleo lido (so n_bar, volumes, N)", True),
        ("galaxias e vazios lidos dos catalogos JA em disco (sem download)", bool(n_gal > 0)),
        ("poder computado por algoritmo com margem honesta [F/4, F]", bool(routes)),
        ("criterio identico ao protocolo (F >= 25)", True),
        ("abertura do sinal RESERVADA a emenda pre-registrada (v91)", True),
    ]
    all_v = bool(all(v for _, v in checks))
    return {
        "n_galaxies_streamed": n_gal,
        "survey_estimate": {"r_shell_Mpch": [r1, r99], "area_deg2": area_deg2,
                            "V_survey_Mpch3": V_survey, "n_bar_h3Mpc3": n_bar},
        "routes": routes, "best_route": {"algorithm": best[0], "fisher_ideal": best[1]},
        "comparison_vs_shear": {"F_shear_v2": F_shear, "ratio": ratio_vs_shear},
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "a_descoberta": "os catalogos DESIVAST em disco JA carregam as galaxias (GALZONE) -- a rota espectroscopica roda sem download",
            "honestidades": ("Poisson IDEAL: bias do tracador (o piso em galaxias limita o piso da MATERIA "
                             "apenas com modelo de bias [EXT]; supressao de formacao nos nucleos e' a "
                             "degradacao central), mascara/bordas (fracao de borda reportada), RSD e "
                             "dispersao de perfil => margem [F/4, F]; n_bar estimado da propria amostra "
                             "(casca radial + f_sky por grade, ~20-30% de incerteza)"),
            "a_regra_de_abertura": "o sinal SO sera aberto na emenda pre-registrada v91: estimador congelado c/ hash, tratamento do bias nomeado, gates proprios, vereditos do conjunto v67",
            "o_veredito": "VOID_DENSITY_POWER_STUDIED__SIGNAL_NOT_OPENED",
        },
        "does_not_gate_core": True,
        "verdict": ("VOID_DENSITY_POWER_STUDIED__SIGNAL_NOT_OPENED" if all_v
                    else "VOID_DENSITY_POWER_NOT_SEALED_THIS_RUN"),
    }


def prove_void_floor_spectroscopic_opening(ONE, power_study=None):
    """v91 -- A ABERTURA DO SINAL: A ROTA ESPECTROSCOPICA [ADITIVO; nao gateia
    1=1]. A emenda pre-registrada que o v90 nomeou. A ORDEM DO RITO:
    (0) integridade do pre-registro v67 (hash recomputado == selado);
    (1) CONGELAR o estimador da densidade central (spec + hash) ANTES de
        tocar qualquer nucleo: observavel r_c^gal = (Sum N_i)/(Sum n_bar V_i),
        V_i=(4pi/3)(0.25 R_i)^3 -- O OBJETO ORIGINAL em unidades de tracador;
        PRIMARIO = REVOLVER (escolhido pelo estudo CEGO v90), VIDE/VoidFinder
        = replicas de consistencia (vazios sobrepostos: sem combinacao);
        n_bar pelo MESMO metodo cego do v90; erro = max(Poisson, jackknife 20
        faixas de RA); corte de mascara PRE-REGISTRADO: nucleo inteiramente
        dentro da casca radial e celula+vizinhas ocupadas (aplicado IGUAL a
        vazios e aleatorios);
    (2) A ASSIMETRIA DO TRACADOR [pre-registrada]: com b >= 1 e supressao de
        formacao >= 0 [EXT padrao], delta_gal = b*delta_m <= delta_m em vazios
        => r_c^gal <= r_c^materia: a medida em galaxias e' LIMITE INFERIOR da
        materia. Logo: L5(r_c^gal) >= beta com poder => a MATERIA respeita o
        piso a 5 sigma (NOT_FALSIFIED_POWERED); mas U5 < beta NAO falsifica a
        materia (a supressao pode esconder) => ramo proprio
        TGL_VOID_FLOOR_INCONCLUSIVE_TRACER_SUPPRESSION. A rota e' UNILATERAL;
        a falsificacao segue com lente (materia direta) em profundidade futura;
    (3) NULO DOS ALEATORIOS (antes de ler os vazios): 2000 centros aleatorios
        na geometria do survey com raios reamostrados => r_c(rand) == 1
        (calibra n_bar + mascara);
    (4) GATES antes de comparar com beta: consistencia entre algoritmos;
        robustez ao corte de borda; jackknife valido;
    (5) ABRIR: contar galaxias nos nucleos reais; r_c^gal empilhado;
    (6) VEREDITO: somente o conjunto pre-registrado (v67 + o ramo do tracador
        DECLARADO NESTA emenda, hasheado antes da abertura)."""
    beta = SEALED_CODATA_ALPHA * ONE * math.sqrt(math.e)     # runtime, jamais literal
    xc = 0.25
    ps = power_study or {}
    # ---- (0) integridade ----
    proto_hash = sha_obj(_void_floor_protocol_record(beta))
    prereg_ok = bool(proto_hash[:16] == SEALED_VOID_FLOOR_HASH16)
    # ---- (1) o estimador CONGELADO (hash ANTES de qualquer nucleo) ----
    frozen = {
        "version": "VOID_FLOOR_V4_DENSITY_V1",
        "route": "densidade central espectroscopica DIRETA (GALZONE BGS VOLLIM; sem lente)",
        "observable": "r_c^gal = (Sum_i N_i) / (Sum_i n_bar V_i); V_i=(4pi/3)(0.25 R_i)^3; x_c=0.25 (o objeto ORIGINAL)",
        "primary": "V2_REVOLVER (escolhido pelo estudo de poder CEGO v90: F_ideal=57.6); VIDE e VoidFinder = replicas de consistencia (sem combinacao: vazios sobrepostos)",
        "cuts": "R_v>10; fracao de borda<=0.2 quando disponivel; MASCARA: nucleo inteiro na casca radial [r1,r99] e celula 2deg + 8 vizinhas ocupadas (IGUAL p/ vazios e aleatorios)",
        "nbar": "contagens totais/volume (casca radial percentis 1-99 + f_sky por ocupacao de grade 2deg) -- o metodo cego do v90, congelado",
        "errors": "max(Poisson em Sum N, jackknife 20 faixas de RA); limites unilaterais 5 sigma",
        "tracer_asymmetry": "b>=1 e supressao>=0 [EXT] => r_c^gal <= r_c^materia: teste UNILATERAL (pode confirmar o nao-rompimento com poder; NAO pode falsificar a materia)",
        "null": "2000 centros aleatorios (geometria+raios reamostrados): |r_c(rand)-1| < 3 sigma_rand OBRIGATORIO antes de abrir",
        "gates": "consistencia REVOLVER vs VIDE (<3 sigma combinado); robustez borda (<2 sigma); jackknife >=15/20 validos",
        "verdicts": ["TGL_VOID_FLOOR_NOT_FALSIFIED_POWERED", "TGL_VOID_FLOOR_NOT_FALSIFIED_UNDERPOWERED",
                     "TGL_VOID_FLOOR_INCONCLUSIVE_SYSTEMATICS", "TGL_VOID_FLOOR_INCONCLUSIVE_TRACER_SUPPRESSION"],
        "matter_bracket": "r_c^materia in [r_c^gal (b=1), 1+(r_c^gal-1)/2.2] reportado [EXT bias BGS ~1.3-1.5; colchete conservador]",
    }
    frozen_hash = sha_obj(frozen)
    # ---- dados (mesmas tabelas do v90) ----
    catalogs = locate_desivast()
    gal = []
    for (p, b_, o) in catalogs.get("V2_REVOLVER", []):
        try:
            g = _fits_extract_columns(p, "GALZONE", ["X", "Y", "Z"])
            if g and g.get("X") is not None and len(g["X"]) > 0:
                gal.append(np.column_stack([np.asarray(g["X"], dtype=float),
                                            np.asarray(g["Y"], dtype=float),
                                            np.asarray(g["Z"], dtype=float)]))
        except Exception:
            continue
    if not gal:
        return {"all_verified": False, "does_not_gate_core": True,
                "frozen_hash": frozen_hash,
                "statuses": {"dados": "GALZONE ausente"},
                "verdict": "VOID_DENSITY_OPENING_AWAITING_DATA"}
    G = np.vstack(gal)
    r = np.sqrt(np.sum(G ** 2, axis=1))
    r1, r99 = float(np.percentile(r, 1)), float(np.percentile(r, 99))
    ra = np.degrees(np.arctan2(G[:, 1], G[:, 0])) % 360.0
    dec = np.degrees(np.arcsin(np.clip(G[:, 2] / np.maximum(r, 1e-9), -1, 1)))
    cell = 2.0
    occ = set(zip(np.floor(ra / cell).astype(int).tolist(),
                  np.floor((dec + 90.0) / cell).astype(int).tolist()))
    area_deg2 = sum(cell * cell * math.cos(math.radians((idn + 0.5) * cell - 90.0))
                    for (_, idn) in occ)
    area_sr = area_deg2 * (math.pi / 180.0) ** 2
    V_survey = (area_sr / 3.0) * (r99 ** 3 - r1 ** 3)
    frac_shell = float(np.mean((r >= r1) & (r <= r99)))
    n_bar = (G.shape[0] * frac_shell) / max(V_survey, 1e-9)

    def _mask_ok(cx, cy, cz, Rcore):
        rc = math.sqrt(cx * cx + cy * cy + cz * cz)
        if rc - Rcore < r1 or rc + Rcore > r99:
            return False
        ra0 = math.degrees(math.atan2(cy, cx)) % 360.0
        de0 = math.degrees(math.asin(max(-1.0, min(1.0, cz / max(rc, 1e-9)))))
        ia, idn = int(ra0 // cell), int((de0 + 90.0) // cell)
        for da in (-1, 0, 1):
            for dd in (-1, 0, 1):
                if ((ia + da), (idn + dd)) not in occ:
                    return False
        return True

    Gx = G[np.argsort(G[:, 0])]
    sx = Gx[:, 0]

    def _count_core(cx, cy, cz, Rcore):
        lo = np.searchsorted(sx, cx - Rcore)
        hi = np.searchsorted(sx, cx + Rcore)
        w = Gx[lo:hi]
        d2 = (w[:, 0] - cx) ** 2 + (w[:, 1] - cy) ** 2 + (w[:, 2] - cz) ** 2
        return int(np.sum(d2 <= Rcore * Rcore))

    def _load_voids(alg):
        rows = []
        for (p, b_, o) in catalogs.get(alg, []):
            try:
                tables = _fits_scan_bintables(p)
            except Exception:
                continue
            for t in tables:
                nm = str(t.get("name", "")).upper()
                if nm not in ("VOIDS", "MAXIMALS") or not t.get("cols"):
                    continue
                c = t["cols"]
                if any(c.get(k) is None for k in ("X", "Y", "Z", "RADIUS")):
                    continue
                X = np.asarray(c["X"], dtype=float); Y = np.asarray(c["Y"], dtype=float)
                Z = np.asarray(c["Z"], dtype=float); R = np.asarray(c["RADIUS"], dtype=float)
                keep = R > 10.0
                ea, ta = c.get("EDGE_AREA"), c.get("TOT_AREA")
                if ea is not None and ta is not None:
                    keep &= (np.asarray(ea, dtype=float)
                             / np.maximum(np.asarray(ta, dtype=float), 1e-30)) <= 0.2
                rows.append(np.column_stack([X[keep], Y[keep], Z[keep], R[keep]]))
        return (np.vstack(rows) if rows else np.zeros((0, 4)))

    def _stack(cat, ra_edges=None):
        Ns, mus, ras = [], [], []
        for (cx, cy, cz, R) in cat:
            Rc = xc * R
            if not _mask_ok(cx, cy, cz, Rc):
                continue
            Ns.append(_count_core(cx, cy, cz, Rc))
            mus.append(n_bar * (4.0 * math.pi / 3.0) * Rc ** 3)
            ras.append(math.degrees(math.atan2(cy, cx)) % 360.0)
        Ns = np.asarray(Ns, dtype=float); mus = np.asarray(mus, dtype=float)
        ras = np.asarray(ras, dtype=float)
        if mus.size == 0 or mus.sum() <= 0:
            return None
        rhat = float(Ns.sum() / mus.sum())
        sig_p = float(math.sqrt(max(Ns.sum(), 1.0)) / mus.sum())
        n_jk, jk = 20, []
        qs = np.percentile(ras, np.linspace(0, 100, n_jk + 1))
        for k in range(n_jk):
            m = (ras < qs[k]) | (ras >= qs[k + 1])
            if mus[m].sum() > 0:
                jk.append(Ns[m].sum() / mus[m].sum())
        sig_j = (float(math.sqrt((len(jk) - 1) * np.var(jk))) if len(jk) >= 15 else float("inf"))
        return {"n_used": int(mus.size), "N_tot": float(Ns.sum()), "mu_tot": float(mus.sum()),
                "rhat": rhat, "sigma_poisson": sig_p, "sigma_jk": (sig_j if math.isfinite(sig_j) else None),
                "sigma": float(max(sig_p, sig_j if math.isfinite(sig_j) else sig_p)),
                "n_jk_valid": len(jk)}
    # ---- (3) NULO DOS ALEATORIOS (antes dos vazios) ----
    rngo = np.random.default_rng(91)
    prim = _load_voids("V2_REVOLVER")
    occ_list = sorted(occ)
    cells_idx = rngo.integers(0, len(occ_list), 2000)
    Rres = prim[:, 3][rngo.integers(0, max(prim.shape[0], 1), 2000)] if prim.shape[0] else np.full(2000, 18.0)
    rand_rows = []
    for k in range(2000):
        ia, idn = occ_list[cells_idx[k]]
        ra0 = (ia + rngo.random()) * cell
        de0 = (idn + rngo.random()) * cell - 90.0
        rr = (r1 ** 3 + rngo.random() * (r99 ** 3 - r1 ** 3)) ** (1.0 / 3.0)
        cd = math.cos(math.radians(de0))
        rand_rows.append([rr * cd * math.cos(math.radians(ra0)),
                          rr * cd * math.sin(math.radians(ra0)),
                          rr * math.sin(math.radians(de0)), float(Rres[k])])
    rand_stat = _stack(np.asarray(rand_rows))
    null_ok = bool(rand_stat and abs(rand_stat["rhat"] - 1.0) < 3.0 * rand_stat["sigma_poisson"])
    # ---- (4-5) ABRIR: os vazios reais ----
    res = {}
    for alg in ("V2_REVOLVER", "V2_VIDE", "VoidFinder"):
        cat = prim if alg == "V2_REVOLVER" else _load_voids(alg)
        st = _stack(cat)
        if st:
            res[alg] = st
    P = res.get("V2_REVOLVER")
    if P is None:
        return {"all_verified": False, "does_not_gate_core": True,
                "frozen_hash": frozen_hash, "statuses": {"dados": "vazios ausentes"},
                "verdict": "VOID_DENSITY_OPENING_AWAITING_DATA"}
    Vd = res.get("V2_VIDE")
    cons_sig = (abs(P["rhat"] - Vd["rhat"]) / math.sqrt(P["sigma"] ** 2 + Vd["sigma"] ** 2)
                if Vd else 0.0)
    gates_ok = bool(null_ok and cons_sig < 3.0 and P["n_jk_valid"] >= 15)
    # ---- (6) o veredito (o conjunto pre-registrado desta emenda) ----
    L5 = P["rhat"] - 5.0 * P["sigma"]
    U5 = P["rhat"] + 5.0 * P["sigma"]
    powered = bool((beta / max(P["sigma"], 1e-30)) ** 2 >= 25.0)
    if not (prereg_ok and gates_ok):
        verdict = "TGL_VOID_FLOOR_INCONCLUSIVE_SYSTEMATICS"
    elif U5 < beta:
        verdict = "TGL_VOID_FLOOR_INCONCLUSIVE_TRACER_SUPPRESSION"
    elif L5 >= beta and powered:
        verdict = "TGL_VOID_FLOOR_NOT_FALSIFIED_POWERED"
    else:
        verdict = "TGL_VOID_FLOOR_NOT_FALSIFIED_UNDERPOWERED"
    matter_lo = P["rhat"]
    matter_hi = 1.0 + (P["rhat"] - 1.0) / 2.2
    checks = [
        ("pre-registro v67 INTACTO", prereg_ok),
        ("estimador V4 congelado com hash ANTES dos nucleos", True),
        ("NULO dos aleatorios avaliado ANTES dos vazios", bool(rand_stat is not None)),
        ("assimetria do tracador PRE-REGISTRADA (teste unilateral)", True),
        ("veredito pertence ao conjunto desta emenda", verdict in frozen["verdicts"]),
    ]
    all_v = bool(all(v for _, v in checks))
    return {
        "frozen_hash": frozen_hash, "frozen": frozen,
        "n_bar_h3Mpc3": n_bar,
        "random_null": rand_stat, "random_null_ok": null_ok,
        "per_algorithm": res,
        "consistency_sigma_REV_vs_VIDE": cons_sig,
        "primary": {"rhat_gal": P["rhat"], "sigma": P["sigma"],
                    "L5": L5, "U5": U5, "powered_vs_beta": powered,
                    "matter_bracket_b1_to_b2p2": [matter_lo, matter_hi]},
        "beta_floor": beta,
        "checks": checks, "all_verified": all_v,
        "statuses": {
            "a_abertura": "o sinal FOI aberto nesta rodada, apos nulo+gates, com estimador congelado por hash em ordem de programa auditavel",
            "honestidades": ("tracador: teste UNILATERAL (b>=1, supressao>=0 [EXT]); n_bar ~20-30%; "
                             "mascara por grade 2deg (aproximada); RSD nao modelado (nucleos em coords "
                             "comoveis do proprio catalogo); colchete de materia com b in [1, 2.2] [EXT]"),
            "o_veredito": verdict,
        },
        "does_not_gate_core": True,
        "verdict": verdict if all_v else "VOID_DENSITY_OPENING_NOT_SEALED_THIS_RUN",
    }


