    wp = -2.0 * (x0[1] - x0[0] - s0) * w_(x0[1] - x0[0])
    kin_num = sum((eps[m, n] * (-1.0) * wp) ** 2 for m in range(4) for n in range(4))
    kin_form = 2.0 * (a_ ** 2 + b_ ** 2) * wp ** 2
    kin_resid = abs(kin_num - kin_form) / max(abs(kin_form), 1e-30)
