    # v370 -- a GNS genuina (ver docstring). np e o unico requisito.
    s0 = [1.0 / 3.0, 1.0 - 1.0 / 3.0]
    s1 = [1.0 / 4.0, 1.0 - 1.0 / 4.0]
    n = 4
    N = n * n
    pw = np.array([x * y for x in s0 for y in s1], dtype=float)
    rt = np.diag(np.sqrt(pw)).astype(complex)          # rho^{1/2}
    rti = np.linalg.inv(rt)                             # rho^{-1/2}
    rho = rt @ rt
    basis = []
    for _i in range(n):
        for _j in range(n):
            _E = np.zeros((n, n), dtype=complex)
            _E[_i, _j] = 1.0
            basis.append(_E)
    vec = lambda a: a.reshape(-1)
    unvec = lambda v: v.reshape(n, n)
    supmat = lambda f: np.column_stack([vec(f(E)) for E in basis])   # superoperador -> 16x16
    ip = lambda a, b: complex(np.trace(rho @ a.conj().T @ b))         # <a,b>_omega
    J = lambda a: rt @ a.conj().T @ rti                               # Tomita para omega fiel
    L = lambda x: supmat(lambda a: x @ a)                             # pi(x): ESQUERDA
    R = lambda x: supmat(lambda a: a @ x)                             # DIREITA
    Phi = lambda T: supmat(lambda a: J(unvec(T @ vec(J(a)))))        # Phi(T) = J T J
    rng = np.random.default_rng(244)
    x = rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n))
    y = rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n))
    T1 = rng.normal(size=(N, N)) + 1j * rng.normal(size=(N, N))
    T2 = rng.normal(size=(N, N)) + 1j * rng.normal(size=(N, N))
    cc = complex(rng.normal(), rng.normal())
    a0 = rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n))
    Om = np.eye(n, dtype=complex)
    nrm = np.linalg.norm
    r_J = max(float(nrm(J(J(x)) - x)), float(abs(ip(J(x), J(y)) - np.conj(ip(x, y)))), float(nrm(J(Om) - Om)))
    _f = lambda a: J(unvec(T1 @ vec(J(a))))
    r_lin_vec = float(nrm(_f(cc * a0 + x) - (cc * _f(a0) + _f(x))))
    # ★ TIPO (v370): T -> JTJ e ANTILINEAR em T (J(cT)J = conj(c) JTJ); cada JTJ e linear nos vetores.
    r_antilin = float(nrm(Phi(cc * T1 + T2) - (np.conj(cc) * Phi(T1) + Phi(T2))))
