    # a TRADUCAO referente->signo, medida: a media do fluxo em [0,T] tem fator
    # (e^{i d T}-1)/(i d T) fora do bloco (d = lw_i - lw_j != 0) -- exato, nao grade
    T_avg = 1.0e6
    fator_max = 0.0
    for i in range(4):
        for j in range(4):
            d = lw[i] - lw[j]
            if abs(d) > 1e-15:
                fator = abs((np.exp(1j * d * T_avg) - 1.0) / (1j * d * T_avg))
