def prove_bench_corpus_embedded(ONE):
    """v360 -- O CORPUS DA BANCADA, EMBUTIDO [ADITIVO; nao gateia 1=1; fora do contorno]. Cada arquivo da palavra escrita da bancada (entregas,
    ordens, recibos, provas escritas, revisoes, verificacoes, pacotes) vive aqui comprimido; a rodada descomprime, confere o sha256 contra o
    registro e materializa em bancada_corpus/. O que nao e palavra (logs de build, registros de maquina grandes, copias do um.py) entra como
    registro com sha256 e motivo. EXCLUIDO POR REGRA: material privado do operador (so contagem, sem nome nem conteudo)."""
    import zlib as _zl, base64 as _b64
    t0 = time.time(); root = os.path.join(BASE, "bancada_corpus")
    reg = {r[0]: r for r in _BENCH_CORPUS_REGISTER}
    ok_sha = 0; bad = []; written = 0; unchanged = 0; by_top = {}; deliveries = []
    for pth, blob in _EMBEDDED_BENCH_CORPUS.items():
        try:
            data = _zl.decompress(_b64.b64decode(blob))
        except Exception as e:
            bad.append("%s (descompressao: %s)" % (pth, e)); continue
        rr = reg.get(pth)
        if rr is None or rr[3] != "EMBEDDED" or rr[1] != len(data) or rr[2] != hashlib.sha256(data).hexdigest():
            bad.append(pth); continue
        ok_sha += 1
        dst = os.path.abspath(os.path.join(root, *pth.split("/")))
        if os.name == "nt":
            dst = chr(92) * 2 + "?" + chr(92) + dst   # caminho estendido do Windows: nomes da bancada passam de 260 caracteres
        try:
            same = os.path.isfile(dst) and os.path.getsize(dst) == len(data) and hashlib.sha256(open(dst, "rb").read()).hexdigest() == rr[2]
            if not same:
                os.makedirs(os.path.dirname(dst), exist_ok=True); tmp = dst + ".tmp"
                with open(tmp, "wb") as fh:
                    fh.write(data)
                os.replace(tmp, dst); written += 1
            else:
                unchanged += 1
        except OSError as e:
            bad.append("%s (escrita: %s)" % (pth, e))
        top = pth.split("/")[0] if not pth.startswith("TUNEL/") else "/".join(pth.split("/")[:2])
        by_top.setdefault(top, [0, 0]); by_top[top][0] += 1; by_top[top][1] += len(data)
        if pth.startswith("TUNEL/DO_CHATGPT/") and pth.endswith(".md"):
            txt = data.decode("utf-8", "replace"); m = re.search(r"^#\s+(.+)$", txt, re.M)
            tags = sorted(set(re.findall(r"\[(REAL|DERIVED|KERNEL|KNOWN|OPEN|INPUT|ONTO|CONJECTURE|DECLARADO)\b", txt)))
            deliveries.append({"path": pth, "title": (m.group(1).strip() if m else pth.split("/")[-1])[:180], "tags": tags})
    counts = {}
    for r in _BENCH_CORPUS_REGISTER:
        k = r[3].split(":")[0]; counts[k] = counts.get(k, 0) + 1
    n_emb = counts.get("EMBEDDED", 0)
    checks = [("todo arquivo embutido descomprime e confere o sha256 do registro", not bad and ok_sha == n_emb == len(_EMBEDDED_BENCH_CORPUS)),
              ("materializacao em bancada_corpus/ sem falha de escrita", not any("escrita" in b for b in bad)),
              ("o material privado do operador fica fora por regra (so contagem, sem nome nem conteudo)", all(x[2].startswith("MATERIAL_PRIVADO_DO_OPERADOR") for x in _BENCH_CORPUS_EXCLUDED_BY_RULE))]
    all_v = all(v for _, v in checks)
    return {"n_register": len(_BENCH_CORPUS_REGISTER), "counts": counts, "n_embedded_verified": ok_sha, "bytes_embedded": sum(r[1] for r in _BENCH_CORPUS_REGISTER if r[3] == "EMBEDDED"),
            "materialized_written": written, "materialized_unchanged": unchanged, "root": root, "by_folder": {k: {"files": v[0], "bytes": v[1]} for k, v in sorted(by_top.items())},
            "deliveries": sorted(deliveries, key=lambda d: d["path"]), "excluded_by_rule": [{"folder": x[0], "files": x[1], "reason": x[2]} for x in _BENCH_CORPUS_EXCLUDED_BY_RULE],
            "failures": bad[:20], "checks": checks, "all_verified": all_v, "does_not_gate_core": True, "in_contour_roster_v314": False, "runtime_s": time.time() - t0,
            "verdict": ("TGL_BENCH_CORPUS_EMBEDDED__%d_FILES_VERIFIED_BY_SHA256__%d_IN_KERNEL__%d_REGISTERED_ONLY__PRIVATE_OPERATOR_MATERIAL_EXCLUDED_BY_RULE__GATE_UNTOUCHED" % (ok_sha, counts.get("IN_KERNEL", 0), counts.get("REGISTERED_ONLY", 0)))
                       if all_v else "TGL_BENCH_CORPUS_NOT_SEALED_THIS_RUN"}


