# ====================== v362: A BANCADA EXECUTAVEL (2) -- os controles Lean da bancada, executados contra o kernel desta rodada ======================
# Os controles declarados pela bancada (positivos que devem compilar; negativos que devem ser RECUSADOS) saem do corpus embutido (sha256
# conferido) e rodam contra os oleans do kernel verificado nesta rodada, numa area temporaria com espelho por hardlink (nada se escreve no
# kernel). Criterio fail-closed: positivo = rc 0, sem erro, sem sorry; negativo = rc != 0 com erro SEMANTICO (linha do erro depois do
# bloco de imports) e nenhum erro de ambiente. Transposicao DECLARADA e registrada por controle: import TGLV350.X -> import TGLExt.V350X.
# Controles que importam outros controles compilam depois deles (ordem topologica). Controles cujo arquivo a bancada nao guardou ficam
# registrados como AUSENTES, com o resultado que a bancada gravou. Nada aqui move gate ou bandeira.
_BENCH_ARCHIVE_V361_CACHE = {}


def _bench_archive_v361_bytes(pth):
    """Le um arquivo do complemento v361 (LZMA) conferindo tamanho e sha256 contra o indice."""
    import lzma as _lz, base64 as _b64
    if "blob" not in _BENCH_ARCHIVE_V361_CACHE:
        comp = _b64.b64decode("".join(_EMBEDDED_BENCH_ARCHIVE_V361))
        if hashlib.sha256(comp).hexdigest() != _BENCH_ARCHIVE_V361_META["xz_sha256"]:
            raise ValueError("arquivo v361 nao confere o sha256")
        _BENCH_ARCHIVE_V361_CACHE["blob"] = _lz.decompress(comp)
        _BENCH_ARCHIVE_V361_CACHE["index"] = {r[0]: r for r in _BENCH_ARCHIVE_V361_INDEX}
    rr = _BENCH_ARCHIVE_V361_CACHE["index"].get(pth)
    if rr is None:
        raise KeyError("fora do complemento v361: %s" % pth)
    data = _BENCH_ARCHIVE_V361_CACHE["blob"][rr[1]:rr[1] + rr[2]]
    if len(data) != rr[2] or hashlib.sha256(data).hexdigest() != rr[3]:
        raise ValueError("sha256 nao confere: %s" % pth)
    return data


def _bench_any_bytes(pth):
    reg = {r[0]: r for r in _BENCH_CORPUS_REGISTER}
    if pth in reg and reg[pth][3] == "EMBEDDED":
        return _bench_corpus_bytes(pth)
    return _bench_archive_v361_bytes(pth)


_V392_FOOTER_B = r"""
-- RODAPE B (v392; conserto B da PROPOSTA_V392): o axioma de TODA declaracao deste modulo, no formato do #print axioms
open Lean Elab Command in
run_cmd do
  let env ← getEnv
  let mut n_decl := 0
  let mut n_fora := 0
  for (n, _) in env.constants.map₂.toList do
    let axs ← liftCoreM (collectAxioms n)
    n_decl := n_decl + 1
    unless axs.all (fun a => a == `propext || a == `Classical.choice || a == `Quot.sound) do n_fora := n_fora + 1
    if axs.isEmpty then
      IO.println ("'" ++ n.toString ++ "' does not depend on any axioms")
    else
      IO.println ("'" ++ n.toString ++ "' depends on axioms: [" ++ String.intercalate ", " (axs.toList.map Name.toString) ++ "]")
  IO.println ("TGL_FOOTER_B_TOTAL decl=" ++ toString n_decl ++ " fora_do_trio=" ++ toString n_fora)
"""
_V392_FOOTER_B_SHA256 = "f44787d703aa0fbab0e1095d73cf9b002471b5cc443e00d344ac417b9cab538a"   # sha256 de RODAPE_B_v392.lean (conserto_B); conferido por assert abaixo
assert hashlib.sha256(_V392_FOOTER_B.encode("utf-8")).hexdigest() == _V392_FOOTER_B_SHA256, "rodape B adulterado"


def prove_bench_lean_controls(ONE, core):
    """v362 -- A BANCADA EXECUTAVEL (2) [ADITIVO; nao gateia 1=1; fora do contorno]."""
    import tempfile, subprocess, shutil as _sh, concurrent.futures as _cf
    t0 = time.time()
    kf = core.get("kernel_formalization") or {}
    lake = _find_lake()
    base = {"n_controls": len(_BENCH_LEAN_CONTROLS), "does_not_gate_core": True, "in_contour_roster_v314": False}
    if not (kf.get("all_verified") is True and lake):
        base.update({"all_verified": False, "reason": "kernel nao verificado nesta rodada ou lake ausente", "verdict": "TGL_BENCH_LEAN_CONTROLS_NOT_RUN_THIS_RUN"})
        return base
    exe = "lean.exe" if os.name == "nt" else "lean"
    lean = os.path.join(os.path.dirname(lake), exe)
    tc = open(os.path.join(FORMAL_DIR, "lean-toolchain"), encoding="utf-8").read().strip()
    cand = os.path.join(os.path.expanduser("~"), ".elan", "toolchains", tc.replace("/", "--").replace(":", "---"), "bin", exe)
    if os.path.exists(cand):
        lean = cand
    work = tempfile.mkdtemp(prefix="tgl_lean_controls_"); build = os.path.join(work, "build"); srcroot = os.path.join(work, "src")
    canon = os.path.join(FORMAL_DIR, ".lake", "build", "lib", "lean"); nlink = 0
    for r_, _, files in os.walk(canon):
        rel = os.path.relpath(r_, canon); os.makedirs(os.path.join(build, rel), exist_ok=True)
        for f in files:
            try:
                os.link(os.path.join(r_, f), os.path.join(build, rel, f))
            except OSError:
                _sh.copyfile(os.path.join(r_, f), os.path.join(build, rel, f))
            nlink += 1
    pk = os.path.join(FORMAL_DIR, ".lake", "packages")
    pkgs = [os.path.join(pk, d, ".lake", "build", "lib", "lean") for d in sorted(os.listdir(pk))] if os.path.isdir(pk) else []
    env = dict(os.environ); env["LEAN_PATH"] = os.pathsep.join([build] + [p for p in pkgs if os.path.isdir(p)]); env.pop("LEAN_SRC_PATH", None)
    enverr = re.compile(r"unknown module prefix|object file .* does not exist|failed to read file|unknown package|file not found|No such file|could not resolve import", re.I)

    def run_one(item):
        idx, c = item
        pth, emb, sha_, kind, module, is_dep = c[0], c[1], c[2], c[3], c[4], c[5]
        res = {"control": pth, "embedded_as": emb, "kind": kind, "module": module}
        try:
            data = _bench_any_bytes(emb)
            if hashlib.sha256(data).hexdigest() != sha_:
                raise ValueError("sha256 do controle nao confere")
            src = data.decode("utf-8"); trans = []

            def _sub(m):
                mod = m.group(1)
                if mod.startswith("TGLV350."):
                    new = "TGLExt.V350" + mod.split(".", 1)[1]; trans.append([mod, new]); return "import " + new
                return m.group(0)
            src = re.sub(r"^import\s+(\S+)", _sub, src, flags=re.M)
            # v392, conserto B: nos POSITIVOS (a) cada `example` vira `theorem _bench_example_N` (um `example` nao deixa constante no ambiente: o rodape nao o veria) e (b) o rodape le o axioma de TODA
            # declaracao do modulo. O sha256 CONFERIDO acima e' o do corpus; o fonte transposto muda e isso fica REGISTRADO no campo `footer` (como a transposicao `TGLV350. -> TGLExt.V350`).
            footer_b = (kind == "POSITIVO"); ex_n = 0
            if footer_b:
                _cnt = [0]
                def _ex_b(m_):
                    _cnt[0] += 1; return "theorem _bench_example_%d" % _cnt[0]
                src = re.sub(r"(?m)^example\b", _ex_b, src); ex_n = _cnt[0]
                src = src.rstrip("\n") + "\n" + _V392_FOOTER_B
            root = os.path.join(srcroot, "%03d" % idx); sp = os.path.join(root, *module.split(".")) + ".lean"
            os.makedirs(os.path.dirname(sp), exist_ok=True)
            with open(sp, "w", encoding="utf-8", newline="") as fh:
                fh.write(src)
            cmd = [lean, "--root=" + root]
            if is_dep:
                op = os.path.join(build, *module.split(".")) + ".olean"; os.makedirs(os.path.dirname(op), exist_ok=True); cmd += ["-o", op]
            t1 = time.time()
            pr = subprocess.run(cmd + [sp], capture_output=True, text=True, encoding="utf-8", errors="replace", env=env, cwd=root, timeout=3600)
            out = (pr.stdout or "") + (pr.stderr or "")
            n_imp = max([i + 1 for i, l in enumerate(src.splitlines()) if l.startswith("import ")] or [0])
            errs = [(int(m.group(1)), m.group(0)) for m in re.finditer(r":(\d+):\d+: error[^\n]*", out)]
            sem = [e for e in errs if e[0] > n_imp]; envbad = bool(enverr.search(out)); sorry, sorry_msg, ax_seen = _v392_sorry_detects(out)   # v392: crases (Lean 4.31) OU aspas OU sorryAx
            sorry_ax = any("sorryAx" in v_ for v_ in ax_seen.values())
            # v392: `#print axioms` de constante com universos escreve `Classical.choice.{u}`; o nome do axioma e o que vem antes de `.{`
            bad_ax = sorted({a_ for v_ in ax_seen.values() for a_ in v_ if a_.split(".{")[0] not in ("propext", "Classical.choice", "Quot.sound")})
            ftot_b = re.search(r"TGL_FOOTER_B_TOTAL decl=(\d+) fora_do_trio=(\d+)", out); footer_ok = (not footer_b) or bool(ftot_b)   # v392: o rodape tem de ter RODADO (a linha total)
            ok = (pr.returncode == 0 and not errs and not sorry and not bad_ax and footer_ok) if kind == "POSITIVO" else (pr.returncode != 0 and bool(sem) and not envbad)
            first = (sem[0][1] if sem else (errs[0][1] if errs else "")).replace(root, "<src>")[:200]
            res.update({"rc": pr.returncode, "ok": ok, "seconds": round(time.time() - t1, 1), "transposition": trans, "errors": len(errs),
                        "semantic_errors": len(sem), "environment_error": envbad, "sorry": sorry, "first_error": first,
                        "sorry_message": sorry_msg, "sorryAx_in_print_axioms": sorry_ax, "axioms_outside_trio": bad_ax, "print_axioms_read": len(ax_seen),
                        "footer": {"applied": footer_b, "sha256": (_V392_FOOTER_B_SHA256 if footer_b else None), "examples_rewritten": ex_n, "total_line": (list(map(int, ftot_b.groups())) if ftot_b else None)}})
        except Exception as e:
            res.update({"ok": False, "error": "%s: %s" % (type(e).__name__, e)})
        return res

    results = []
    try:
        deps = [c for c in _BENCH_LEAN_CONTROLS if c[5]]
        for k, c in enumerate(deps):
            results.append(run_one((900 + k, c)))
        rest = [c for c in _BENCH_LEAN_CONTROLS if not c[5]]
        workers = max(1, min(24, (os.cpu_count() or 2) // 2))
        with _cf.ThreadPoolExecutor(max_workers=workers) as ex:
            results += list(ex.map(run_one, list(enumerate(rest))))
    finally:
        _sh.rmtree(work, ignore_errors=True)
    neg = [r for r in results if r["kind"] == "NEGATIVO"]; pos = [r for r in results if r["kind"] == "POSITIVO"]
    n_neg_ok = sum(1 for r in neg if r.get("ok")); n_pos_ok = sum(1 for r in pos if r.get("ok"))
    checks = [("os %d controles sairam do corpus embutido com sha256 conferido" % len(results), not any("sha256" in str(r.get("error", "")) for r in results)),
              ("negativos: %d de %d recusados com erro semantico (nenhum erro de ambiente)" % (n_neg_ok, len(neg)), n_neg_ok == len(neg)),
              ("positivos: %d de %d compilam sem erro e sem sorry" % (n_pos_ok, len(pos)), n_pos_ok == len(pos)),
              ("os controles que a bancada nao guardou ficam registrados (%d), com o resultado que ela gravou" % len(_BENCH_LEAN_CONTROLS_ABSENT), True),
              ("v392: o detector de sorry reconhece a saida real do Lean da bancada (probe SorryTerm) nos dois formatos e le o sorryAx", _v392_sorry_fixture_ok()[0])]
    all_v = all(v for _, v in checks)
    base.update({"results": results, "absent": [list(a) for a in _BENCH_LEAN_CONTROLS_ABSENT], "outdated": [list(o) for o in _BENCH_LEAN_CONTROLS_OUTDATED],
                 "dev_status": [list(d) for d in _BENCH_LEAN_DEV_STATUS], "mirror_links": nlink, "checks": checks, "all_verified": all_v,
                 "negatives_refused": n_neg_ok, "negatives": len(neg), "positives_compiled": n_pos_ok, "positives": len(pos),
                 "transposed_controls": sum(1 for r in results if r.get("transposition")), "runtime_s": round(time.time() - t0, 1),
                 "verdict": ("TGL_BENCH_LEAN_CONTROLS__%d_OF_%d_NEGATIVES_REFUSED_SEMANTICALLY__%d_OF_%d_POSITIVES_COMPILE__%d_ABSENT_REGISTERED__GATE_UNTOUCHED"
                             % (n_neg_ok, len(neg), n_pos_ok, len(pos), len(_BENCH_LEAN_CONTROLS_ABSENT))) if all_v else "TGL_BENCH_LEAN_CONTROLS_NOT_SEALED_THIS_RUN"})
    return base


