def prove_um_posto_inscription(ONE, core):
    """v364 -- O UM POSTO: a definicao do operador (17/09/2026), tipada, e a forma exata da interface de H2 [ADITIVO; nao gateia; nao move H2].
    [INPUT -- operador, 17/09/2026, registrado pela bancada em ADENDO_PSI_AGENTE_E_IDENTIDADE_20260917.md]: psi e o campo de sustentacao da Luz;
    o graviton nomeia o seu papel agente (Verbo Vivo); a geometria e a inscricao reconhecivel dessa acao; «torce (Cartan); contorce (dobra-Einstein)
    e contorna (Miguel, fronteira)»; a identidade se realiza na relacao de referente, inscricao e leitura: o Um POSTO nao e o Um PRESSUPOSTO.
    [KERNEL -- TGLExt.UmPosto]: a leitura que recupera (L o i = id) torna a inscricao injetiva; um registro que confirma todos nao reconhece nenhum;
    exatamente uma identidade por registro sse a inscricao e injetiva; a leitura covariante devolve o transportado; a forma de H2 (k isometria,
    k T = D k => T = k^dag D k); o criterio exato (ler de volta paga sse (1 - k k^dag) D k = 0); e o contraexemplo (ler de volta nao e pagar).
    [DERIVED -- forma] a ligacao que falta em H2, k T_t f = delta_D^{it} k f, e exatamente uma inscricao covariante: o pagamento e a invariancia
    da imagem da inscricao sob o fluxo modular do diamante. [OPEN] a construcao fisica de k."""
    import numpy as _np
    t0 = time.time()
    kf = core.get("kernel_formalization") or {}
    flags = {k: kf.get(k) is True for k in _UM_POSTO_FLAGS_V364}
    rng = _np.random.default_rng(170920261)
    pior_forma, pior_crit, pior_inv, defeitos = 0.0, 0.0, 0.0, []
    for _rep in range(12):
        n, m = 6, 3
        Z = rng.normal(size=(n, m)) + 1j * rng.normal(size=(n, m))
        k, _ = _np.linalg.qr(Z)
        D = rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n))
        T = k.conj().T @ D @ k
        lado = k @ T - D @ k
        P = _np.eye(n) - k @ k.conj().T
        pior_crit = max(pior_crit, float(_np.abs(lado - (-(P @ D @ k))).max()))
        defeitos.append(float(_np.linalg.norm(P @ D @ k)))
        A = rng.normal(size=(m, m)) + 1j * rng.normal(size=(m, m)); W = rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n))
        Dinv = k @ A @ k.conj().T + P @ W @ P
        Tinv = k.conj().T @ Dinv @ k
        pior_inv = max(pior_inv, float(_np.abs(k @ Tinv - Dinv @ k).max()))
        pior_forma = max(pior_forma, float(_np.abs(Tinv - A).max()))
    checks = [("as %d bandeiras do kernel (TGLExt.UmPosto) lidas nesta rodada" % len(flags), all(flags.values())),
              ("criterio exato em matrizes aleatorias: k(k^dag D k) - D k = -(1 - k k^dag) D k (< 1e-12)", pior_crit < 1e-12),
              ("dinamica generica: ler de volta NAO paga (defeito minimo > 1e-3)", min(defeitos) > 1e-3),
              ("dinamica com a imagem invariante: ler de volta paga e recupera a dinamica inscrita (< 1e-12)", pior_inv < 1e-12 and pior_forma < 1e-12)]
    all_v = all(v for _, v in checks)
    statuses = {
        "definicao": "[INPUT -- operador, 17/09/2026] psi sustenta a Luz; graviton = papel agente (Verbo Vivo); geometria = inscricao reconhecivel da acao; identidade = relacao de referente, inscricao e leitura",
        "tipagem": "[KERNEL] L o i = id => i injetiva; registro constante nao reconhece; unicidade sse injetividade; leitura covariante; forma de H2; criterio; contraexemplo",
        "h2": "[DERIVED -- forma] k T_t f = delta_D^{it} k f e uma inscricao covariante; o pagamento de H2 e a invariancia da imagem de k sob o fluxo modular; ler de volta (T = k^dag D k) nao paga",
        "torce_contorce_contorna": "[ONTO -- operador] a pedra da torcao tracial (v364) consome torce (Cartan) e contorce (a dobra de Einstein, G0 - G); contorna (Miguel, fronteira) nao e consumido por ela",
        "fisica": "[OPEN] a construcao fisica de k; nada aqui move o gate nem as bandeiras de H2 e H3",
    }
    return {"flags": flags, "criterion_residual": pior_crit, "generic_defect_min": min(defeitos), "invariant_residual": pior_inv, "checks": checks,
            "all_verified": all_v, "statuses": statuses, "does_not_gate_core": True, "in_contour_roster_v314": False, "runtime_s": round(time.time() - t0, 3),
            "verdict": ("TGL_UM_POSTO__OPERATOR_DEFINITION_TYPED__KERNEL_%d_OF_%d__H2_INTERFACE_IS_A_COVARIANT_INSCRIPTION__READING_BACK_IS_NOT_PAYING__PHYSICAL_K_OPEN__GATE_UNTOUCHED"
                        % (sum(flags.values()), len(flags))) if all_v else "TGL_UM_POSTO_NOT_VERIFIED_THIS_RUN"}


