def prove_torsion_shear_dynamics_v365(ONE, core):
    """v365 -- A VISCOSIDADE NEGATIVA NA DINÂMICA: O CISALHAMENTO DECAI [ADITIVO; não gateia].
    Em Bianchi I com a torção tracial (A = alpha n), geometria de Levi-Civita e matéria perfeita, a parte sem traço de G0 = kappa(T^mat + T^tors) é
    sigma' = -(3H - 2 alpha) sigma: o lado de Einstein dá sigma' + 3H sigma e o fornecedor dá +2 alpha sigma (a viscosidade de cisalhamento negativa).
    No ramo em expansão, H >= alpha, a taxa é >= alpha > 0: o cisalhamento sempre decai e só chega a zero no limite do infinito (e^(-alpha t) na
    assíntota H = alpha; com o mesmo H e sem o termo do fornecedor, a taxa seria 3H = 3 alpha): a torção desacelera o decaimento, não o inverte. Leitura de Eckart [CONDICIONAL]:
    na produção de entropia o termo de cisalhamento entra com o sinal de eta (negativo); expansão e calor entram positivos; o balanço completo
    segue [OPEN]. A leitura do operador (resfria e impulsiona ao zero no infinito; a fronteira impede a chegada por acoplamento não mínimo) é
    [ONTO]; a pedra não deriva o piso."""
    import numpy as _np
    t0 = time.time()
    kf = core.get("kernel_formalization") or {}
    flags = {k: kf.get(k) is True for k in _TORSION_SHEAR_FLAGS_V365}
    rng = _np.random.default_rng(20260917)

    def levi_civita(g, dg, ddg):
        gi = _np.linalg.inv(g); dgi = -_np.einsum('ap,pqk,qd->adk', gi, dg, gi)
        Lb = _np.einsum('dcb->dbc', dg) + dg - _np.einsum('bcd->dbc', dg)
        dLb = _np.einsum('dcbe->dbce', ddg) + ddg - _np.einsum('bcde->dbce', ddg)
        return gi, dgi, 0.5 * _np.einsum('ad,dbc->abc', gi, Lb), 0.5 * (_np.einsum('ade,dbc->abce', dgi, Lb) + _np.einsum('ad,dbce->abce', gi, dLb))

    def einstein(G, dG, g, gi):
        R = (_np.einsum('adbc->abcd', dG) - _np.einsum('acbd->abcd', dG) + _np.einsum('ace,edb->abcd', G, G) - _np.einsum('ade,ecb->abcd', G, G))
        Ric = _np.einsum('abad->bd', R); Rs = _np.einsum('bd,bd->', gi, Ric)
        return Ric - 0.5 * g * Rs

    ks = []; anti = 0.0
    for _rep in range(12):
        n = 4; t = float(rng.uniform(0.1, 0.9)); alpha = float(rng.uniform(0.05, 0.8)); c = rng.uniform(-0.4, 0.8, size=(3, 3))
        a = _np.array([1 + c[i, 0] * t + c[i, 1] * t ** 2 + c[i, 2] * t ** 3 for i in range(3)])
        ad = _np.array([c[i, 0] + 2 * c[i, 1] * t + 3 * c[i, 2] * t ** 2 for i in range(3)])
        add = _np.array([2 * c[i, 1] + 6 * c[i, 2] * t for i in range(3)])
        if _np.any(a <= 0.2): continue
        g = _np.diag([-1.0] + list(a * a)); dg = _np.zeros((n, n, n)); ddg = _np.zeros((n, n, n, n))
        for i in range(3):
            dg[i + 1, i + 1, 0] = 2 * a[i] * ad[i]; ddg[i + 1, i + 1, 0, 0] = 2 * (ad[i] ** 2 + a[i] * add[i])
        gi, dgi, G0, dG0 = levi_civita(g, dg, ddg)
        nl = _np.zeros(n); nl[0] = -1.0; A = alpha * nl; I = _np.eye(n); Aup = gi @ A; dAup = _np.einsum('adk,d->ak', dgi, A)
        K = _np.einsum('ab,c->abc', I, A) - _np.einsum('bc,a->abc', g, Aup)
        dK = -_np.einsum('bck,a->abck', dg, Aup) - _np.einsum('bc,ak->abck', g, dAup)
        Gl0 = einstein(G0, dG0, g, gi); Gl = einstein(G0 + K, dG0 + dK, g, gi)
        anti = max(anti, float(_np.abs(Gl - Gl.T).max()))   # F = dA = 0 para A = alpha n com alpha constante: o setor antissimétrico some
        sup = 0.5 * ((Gl0 - Gl) + (Gl0 - Gl).T)
        Hi = ad / a; H = Hi.mean(); sig = Hi - H; dHi = add / a - (ad / a) ** 2; dsig = dHi - dHi.mean()
        mix = lambda X: _np.array([X[i + 1, i + 1] / a[i] ** 2 for i in range(3)])
        G0tf = mix(Gl0) - mix(Gl0).mean(); Stf = mix(sup) - mix(sup).mean()
        M = _np.column_stack([dsig, H * sig]); k12 = _np.linalg.lstsq(M, G0tf, rcond=None)[0]
        k3 = float(_np.dot(Stf, alpha * sig) / _np.dot(alpha * sig, alpha * sig))
        ks.append((float(k12[0]), float(k12[1]), k3, float(_np.abs(M @ k12 - G0tf).max()), float(_np.abs(Stf - k3 * alpha * sig).max())))
    K_ = _np.array(ks)
    k1, k2, k3 = float(K_[:, 0].mean()), float(K_[:, 1].mean()), float(K_[:, 2].mean())
    desv = float(max(_np.abs(K_[:, 0] - 1).max(), _np.abs(K_[:, 1] - 3).max(), _np.abs(K_[:, 2] - 2).max()))
    res = float(max(K_[:, 3].max(), K_[:, 4].max()))
    Hs = _np.linspace(0.3, 3.0, 50); taxa_min = float(min(3 * h - 2 * 0.3 for h in Hs))
    checks = [("as %d bandeiras do kernel (TGLExt.TorsionShearDecay) lidas nesta rodada" % len(flags), all(flags.values())),
              ("Bianchi I, %d fundos não lineares: o lado de Einstein é sigma' + 3H sigma e o fornecedor é +2 alpha sigma (< 1e-9)" % len(ks), len(ks) >= 8 and desv < 1e-9 and res < 1e-9),
              ("o setor antissimétrico da equação some nesses fundos (F = dA = 0; < 1e-12)", anti < 1e-12),
              ("no ramo em expansão (H >= alpha) a taxa 3H - 2alpha é >= alpha > 0 (amostra)", taxa_min >= 0.3 - 1e-12)]
    all_v = all(v for _, v in checks)
    statuses = {
        "dinamica": "[DERIVED -- medido] sigma' = -(3H - 2 alpha) sigma em Bianchi I com a torção tracial e matéria perfeita",
        "condicao": "[CONDICIONAL -- ressalva da bancada] vale para a equação simétrica G_(mu nu)(Gamma) = kappa Theta com Theta = matéria perfeita sem dependência em C e a torção tracial PRESCRITA; a equação da conexão não é resolvida aqui; o setor antissimétrico some porque F = dA = 0",
        "ramo_em_expansao": "[KERNEL] H = alpha + sqrt(kappa rho/3) >= alpha => taxa >= alpha > 0: o cisalhamento sempre decai; na assíntota H = alpha a taxa vale alpha (com o mesmo H e sem o fornecedor seria 3 alpha)",
        "eckart": "[CONDICIONAL -- fluido imperfeito] na produção de entropia de Eckart os coeficientes lidos são zeta = (4/3) alpha/kappa > 0, eta = -alpha/kappa < 0, kappa_T T = alpha/kappa > 0: o termo de cisalhamento entra negativo, expansão e calor entram positivos; o balanço completo [OPEN]",
        "ritmo": "[DERIVED] a torção desacelera o decaimento do cisalhamento (taxa 3H - 2 alpha < 3H), não o inverte no ramo em expansão",
        "leitura_do_operador": "[ONTO -- verbatim] a viscosidade negativa resfria e impulsiona ao zero absoluto no limite do infinito; a fronteira impede a chegada por acoplamento não mínimo; a tríade da formação tridimensional",
        "escala": "[INPUT] alpha = theta_M/((n-1) ell); ell não fixado",
    }
    return {"flags": flags, "coefficients": {"k_sigma_dot": k1, "k_H_sigma": k2, "k_alpha_sigma": k3}, "max_coefficient_deviation": desv, "max_residual": res,
            "n_backgrounds": len(ks), "antisymmetric_max": anti,
            "checks": checks, "all_verified": all_v, "statuses": statuses, "does_not_gate_core": True, "in_contour_roster_v314": False, "runtime_s": round(time.time() - t0, 2),
            "verdict": ("TGL_TORSION_SHEAR_DYNAMICS__BIANCHI_I_SIGMA_DOT_EQ_MINUS_3H_MINUS_2ALPHA_SIGMA__DECAYS_ON_EXPANDING_BRANCH__ZERO_ONLY_AT_INFINITY__KERNEL_%d_OF_%d__GATE_UNTOUCHED"
                        % (sum(flags.values()), len(flags))) if all_v else "TGL_TORSION_SHEAR_DYNAMICS_NOT_VERIFIED_THIS_RUN"}


