    ck_("m11", "(1/2) I e' fixado pelo colapso e por toda conjugacao pela matriz-S: S (1/2 I) S^T = 1/2 I (Psibit.half_identity_is_a_fixed_point)", r_fix_ <= 1e-15, r_fix_)
