def _ledger_counts_v389(ate=None):
    # v390 (07/10/2026), AO LADO: `ate` (o numero da versao) conta so as pedras do ledger ate essa versao e tira do conjunto embutido os caminhos das pedras
    # posteriores -- o registro da v389 le o estado da v389 (1025/156/156); a Parte C le o vivo (ate=None). O pino da v389 NAO se reconta: recontar faria a v389
    # dizer que o exame errou por 11 (ele errou por 10; o +1 e' a pedra da v390) -- achado da afericao adversarial da v390.
    """v389 (06/10/2026): as contagens da Parte C, LIDAS do proprio arquivo em runtime (nunca digitadas): (caminhos unicos do ledger _ESQUELETO_STONES,
    arquivos TGLExt/*.lean embutidos FORA do ledger, quantos destes em TGLExt/O16). A frase do artigo diz o recorte (o exame da v388, errata ao lado: 1025, nao 1015)."""
    _ver_ = lambda s_: int(str(s_[0])[1:]) if str(s_[0])[:1] == "v" and str(s_[0])[1:].isdigit() else 0
    _tup_ = [s_ for s_ in _ESQUELETO_STONES if isinstance(s_, tuple) and len(s_) > 2]
    led_ = {s_[2] for s_ in _tup_ if ate is None or _ver_(s_) <= ate}
    post_ = set() if ate is None else {s_[2] for s_ in _tup_ if _ver_(s_) > ate}
    ext_ = {k_ for k_ in _EMBEDDED_KERNEL_FILES if k_.startswith("TGLExt/") and k_.endswith(".lean")} - post_
    fora_ = ext_ - led_
    return len(led_), len(fora_), sum(1 for f_ in fora_ if f_.startswith("TGLExt/O16/"))


