    ledger = []
    for cid, lado, crit, registro, lei, chave, token, desfecho, how, spec, in_rule, extras in _V383_LEDGER_INPUT:
        vpath = (spec or {}).get("verdict_path") if how == "TOKEN_CONTAINS" else None
