def _self_sha16():
    """v376: o sha256/16 DESTE arquivo, lido do disco no momento da emissao (nunca de memoria) -- o carimbo dos .md emitidos."""
    try:
        with open(os.path.abspath(__file__), "rb") as fh:
            return hashlib.sha256(fh.read()).hexdigest()[:16]
    except Exception:
        return "NAO_LIDO"


def _v376_same_alpha_literal():
    """O script embutido do nivel 2 (texto dentro deste arquivo) tem o seu proprio literal ALPHA_FINE_CODATA_2018; aqui se le esse literal do
    proprio arquivo e se confere que e o MESMO numero de SEALED_CODATA_ALPHA (um dado, dois nomes -- dito, nao escondido)."""
    try:
        with open(os.path.abspath(__file__), "rb") as fh:
            src = fh.read().decode("utf-8", "replace")
        m = re.search(r"^ALPHA_FINE_CODATA_2018 = ([0-9.eE+-]+)", src, re.M)
        return bool(m) and float(m.group(1)) == SEALED_CODATA_ALPHA
    except Exception:
        return False


def _write_text_atomic(path, text):
    """v376 (regra do backup imediato, emenda 22/08): NUNCA open(p,'w') direto -- temporario -> conferir bytes -> os.replace. Um write que falhe
    nao deixa o arquivo vazio (o selo hashearia um vazio)."""
    data = text.encode("utf-8")
    tmp = path + ".tmp_v376"
    with open(tmp, "wb") as fh:
        fh.write(data)
    with open(tmp, "rb") as fh:
        if fh.read() != data:
            raise OSError("escrita atomica: o temporario nao confere: %s" % tmp)
    os.replace(tmp, path)
    return path


def _read_external_json_with_hashes(path):
    """v376 (auditoria 28/09, EV-08, AO LADO de _read_external_json_with_hash): le o artefato UMA vez em bytes e devolve
    (json, sha16 do TEXTO decodificado como a funcao antiga, sha16 dos BYTES). Em arquivo CRLF os dois diferem -- a diferenca e DITA, nao escondida.
    Ausencia => (None, None, None), jamais 'ok' falso."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
        txt = raw.decode("utf-8")
        return (json.loads(txt), hashlib.sha256(txt.encode("utf-8")).hexdigest()[:16], hashlib.sha256(raw).hexdigest()[:16])
    except Exception:
        return None, None, None


def _is_refuted_v376(v):
    """v376 (auditoria 28/09, EV-11, AO LADO de _is_refuted da v200): regra POR SEGMENTO -- um veredito e refutado se algum segmento (entre '__')
    traz FALSIFIED / REFUTED / EXCLUDED / EXCLUDES sem NOT_/UN/NEVER imediatamente antes. 'P1_NOT_FALSIFIED__P2_FALSIFIED' le True (a v200 lia
    False); 'NOT_EXCLUDED_AT_THRESHOLD' le False. Nao substitui a v200 (o veredito dela e pinado): e a leitura ao lado."""
    if not v:
        return False
    for seg in re.split(r"__+", str(v)):
        toks = seg.split("_")
        for i, t in enumerate(toks):
            # negacao ate DOIS tokens antes (NOT_YET_FALSIFIED, CANNOT_BE_FALSIFIED, NON_FALSIFIED, NOT_FALSIFIED -- aferidor B3)
            if t in ("FALSIFIED", "REFUTED", "EXCLUDED", "EXCLUDES") and not any(toks[j] in ("NOT", "UN", "NEVER", "NON", "CANNOT", "YET", "NO") for j in range(max(0, i - 2), i)):
                return True
    return False


def _v376_kernel_ringdown_mentions():
    """MEDIDA no kernel EMBUTIDO: toda mencao a ringdown/quasinormal/QNM esta em comentario ou docstring? Devolve (n_mencoes, declaracoes)."""
    try:
        files = _EMBEDDED_KERNEL_FILES
    except NameError:
        return -1, ["_EMBEDDED_KERNEL_FILES ausente"]
    n, decls = 0, []
    for rel, txt in files.items():
        if not rel.endswith(".lean"):
            continue
        for ln in txt.splitlines():
            if re.search(r"(?i)ringdown|quasinormal|\bQNM\b", ln):
                n += 1
                if re.match(r"^\s*(theorem|lemma|def|structure|abbrev|noncomputable def|instance)\b", ln):
                    decls.append("%s: %s" % (rel, ln.strip()[:100]))
    return n, decls


