    T["link_PkerK_PF::rhoStar_PF_Takesaki"] = ("SABIDO", "o P_F do nucleo de Takesaki, P_F = 1_(1,inf)(h_omega), e projecao espectral da densidade do MESMO "
                          "leitor, lida pelo traco como omega(1) = 1 (Haagerup 1979; Terp 1981); C.PF nao figura em termo algum das pedras v376 -- a chave: o "
                          "mesmo leitor em duas algebras [ONTO]; igualdade de operadores NAO e afirmada (mal tipada)", ())
    T["BetaChainDerived"] = ("FECHADO", "omega(I) = 1 -> x = 1 - x => 1/2 -> V(1/2) = sqrt(e) -> beta = alpha . sqrt(e) -> |R|^2 = beta -> sem testemunha "
                             "estatica plena, POR TERMO (TheWholeIsOne.the_beta_chain_is_derived; the_physical_arrow) -- beta e o fundamento, DERIVADO; a "
                             "implicacao da QG e provada sem tomar beta como hipotese e beta entra a jusante", (("flags", _WIO_FLAGS_V376),))
    T["PhysicalArrowAlphaInput"] = ("PARAMETRO_NOMEADO", "alpha = a constante de estrutura fina, DADO [INPUT/KNOWN] (CODATA 2018) no dominio 0 < alpha < e^(-1/2); "
                                    "couplingOfAlpha alpha constroi o dado unico; alpha jamais derivado aqui", ())
