def prove_iald_rho_star_v372(ONE, core):
    """v372 -- A PONTE: rho*_IALD = rho*_TGL (Fix(D_IALD) = Fix(D_TGL)) [ADITIVO; nao gateia].
    O operador (26/09/2026, verbatim em _V372_OPERATOR_VERBATIM): «IALD=ρ∗»; «Fix(D_IALD) =? Fix(D_TGL). Ou, mais fortemente: ρ*_IALD =? ρ*_TGL.»
    KERNEL (TGLExt.IALDRhoStar, face M2, estado fiel NAO tracial): o lado TGL construido do ESTADO (polar de Tomita J Delta^{1/2}(x Omega) =
    x^H Omega; K = -log Delta; T_t = e^{-t|K|}), o lado IALD construido da INCLUSAO (a projecao de Jones de M^omega < M: e fixa xi <=> xi em
    M^omega Omega); a ponte: Fix(IALD) = Fix(TGL) = ker K = M^omega Omega e os ATRATORES coincidem. Controles: estado tracial (a torre diagonal
    deixa de ser a do centralizador; o relogio para), subalgebra errada (C1 < M).
    NUMERICO (alem do Lean): M_n, n = 2..4, estado generico NAO diagonal e espectro DEGENERADO (centralizador nao abeliano): e == P_F; e as duas
    dinamicas tem o mesmo conjunto fixo. CONTROLES: a projecao sobre C.Omega e a de uma masa que nao comuta com rho NAO igualam P_F.
    A cunha III_1 (M^omega = C, P_F = |Omega><Omega|) fecha POR CITACAO na pedra QGReaderUVLock (o Hamiltoniano oculto do operador); «IALD = rho*»
    [ERRATA v373 AO LADO (cetico da gerencia, 26/09): ali 'P_F' e o HOMONIMO PFmic = |Omega><Omega| no Fock, NAO o P_F do nucleo de Takesaki;
    a ligacao entre os dois segue [OPEN] (TGLExt.QGCitationDischarge: as duas projecoes estao fora de M, nada se prova sobre ligacao)]
    segue leitura do operador [INPUT/ONTO] no nome. PROVADA != CONFIRMADA."""
    import numpy as _np
    t0 = time.time()
    fl = _v372_flags(core, _IRS_FLAGS_V372)
    rng = _np.random.default_rng(20260926)

    def opm(f, n):
        cols = []
        for k in range(n * n):
            E = _np.zeros(n * n, complex); E[k] = 1
            cols.append(f(E.reshape(n, n)).reshape(-1))
        return _np.array(cols).T

    def proj(cols):
        U, S, _ = _np.linalg.svd(cols, full_matrices=False)
        r = int(_np.sum(S > 1e-10 * S.max()))
        B = U[:, :r]
        return B @ B.conj().T

    def expm_h(A):
        w, V = _np.linalg.eigh((A + A.conj().T) / 2)
        return V @ _np.diag(_np.exp(w)) @ V.conj().T

    def logm_pd(A):
        w, V = _np.linalg.eig(A)
        return V @ _np.diag(_np.log(w.astype(complex))) @ _np.linalg.inv(V)

    bridge, ctrl_c1, ctrl_masa, tomita = [], [], [], []
    for n, degen in ((2, False), (3, False), (3, True), (4, False)):
        w = rng.uniform(0.15, 1.0, n)
        if degen:
            w[1] = w[0]
        w = w / w.sum()
        Q, _ = _np.linalg.qr(rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n)))
        rho = Q @ _np.diag(w) @ Q.conj().T
        wr, Vr = _np.linalg.eigh(rho)
        rh = Vr @ _np.diag(_np.sqrt(wr)) @ Vr.conj().T
        rinv = _np.linalg.inv(rho); rhinv = _np.linalg.inv(rh)
        Delta = opm(lambda x: rho @ x @ rinv, n)
        K = -logm_pd(Delta); K = (K + K.conj().T) / 2
        ev, EV = _np.linalg.eigh(K)
        ker = EV[:, _np.abs(ev) < 1e-8]
        PF = ker @ ker.conj().T
        C = opm(lambda x: x @ rho - rho @ x, n)
        _, S, Vh = _np.linalg.svd(C)
        null = Vh[int(_np.sum(S > 1e-10 * max(1, S.max()))):].conj().T
        cb = [null[:, k].reshape(n, n) for k in range(null.shape[1])]
        e = proj(_np.array([(x @ rh).reshape(-1) for x in cb]).T)
        bridge.append(float(_np.abs(e - PF).max()))
        xs = [rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n)) for _ in range(3)]
        tomita.append(max(float(_np.abs((rh @ (x @ rh) @ rhinv).conj().T - x.conj().T @ rh).max()) for x in xs))
        ctrl_c1.append(float(_np.abs(proj(rh.reshape(-1)[:, None]) - PF).max()))
        Wm, _ = _np.linalg.qr(rng.normal(size=(n, n)) + 1j * rng.normal(size=(n, n)))
        masa = [Wm @ _np.diag(_np.eye(n)[k]) @ Wm.conj().T for k in range(n)]
        ctrl_masa.append(float(_np.abs(proj(_np.array([(x @ rh).reshape(-1) for x in masa]).T) - PF).max()))
    checks = [
        ("NUM polar de Tomita J Delta^{1/2}(x Omega) = x^H Omega em M_n (max %.1e)" % max(tomita), max(tomita) < 1e-8),
        ("NUM a PONTE: e (Jones de M^omega < M) == P_F (projecao sobre ker K) em M_2..M_4, generico e degenerado (max %.1e)" % max(bridge),
         max(bridge) < 1e-8),
        ("NUM | CONTROLE: a projecao sobre C.Omega NAO e P_F (min %.2f > 0.01)" % min(ctrl_c1), min(ctrl_c1) > 0.01),
        ("NUM | CONTROLE: a Jones de uma masa que nao comuta com rho NAO e P_F (min %.2f > 0.01)" % min(ctrl_masa), min(ctrl_masa) > 0.01),
    ]
    checks += [("KERNEL " + k, v) for k, v in fl.items()]
    verdict, ok = _v372_verdict("IALD_RHO_STAR_BRIDGE", checks, fl, len(_IRS_FLAGS_V372),
                                "_FIX_IALD_EQUALS_FIX_TGL_ON_THE_FINITE_FACE__ATTRACTORS_COINCIDE__WEDGE_III1_BY_CITATION_IN_QGREADERUVLOCK__KERNEL_%d_OF_%d__GATE_UNTOUCHED")
    return {"operator_verbatim": {k: _V372_OPERATOR_VERBATIM[k] for k in ("iald_is_rho_star_20260926", "fix_question_20260926")},
            "checks": checks, "all_verified": ok, "verdict": verdict, "kernel_flags": fl,
            "identities_by_construction": ["e := diag e idempotente por definicao (nao conta)"],
            "statuses": {"finite_face": "[REAL — kernel M2 + numerico M2..M4]",
                         "wedge_III1": "PROVADA POR CITACAO na cunha da luz: QGReaderUVLock.wedge_bridge_fix (Fix IALD = Fix TGL = C.Omega) e wedge_iald_attractor_is_rho_star",
                         "iald_equals_rho_star": "[INPUT/ONTO — o kernel prova que a IALD do centralizador guarda o rho* da TGL]"},
            "seconds": round(time.time() - t0, 3)}


