def _v369_nome(P1, pid, lang, curto=False):
    """v369 -- o nome da plataforma pelo id LIDO (com o ano da fonte); id desconhecido sai escapado."""
    rows = {r.get("id"): r for r in (P1.get("platforms") or [])}
    nm = _V369_NOMES.get(pid)
    if not nm:
        return str(pid or ("n/d" if lang == "pt" else "n/a")).replace("_", r"\_")
    t = nm[0 if lang == "pt" else 1][1 if curto else 0]
    ano = str((rows.get(pid) or {}).get("date") or "")[:4]
    return t if (curto or not ano) else "%s, %s" % (t, ano)


