def _v369_ao_lado(core, lang, onde):
    """v369 -- as frases AO LADO do artigo, nos pontos que prometiam sem o numero (regra 11: a frase falsa nao fica viva onde e' lida).
    Cada palavra de veredito e cada NOME de plataforma e' LIDO do nucleo desta rodada (forma = conteudo): sem o modulo, sem o dado do LIGO
    ou com a injecao reprovada, a frase diz isso."""
    ck = core.get("clock_test_result_v369") or {}
    p1 = (ck.get("P1") or {}).get("verdict"); p2 = (ck.get("P2") or {}).get("verdict")
    rl = ck.get("root_law") or {}; P1 = ck.get("P1") or {}
    selado = bool(ck) and not str(ck.get("verdict", "")).startswith("TGL_CLOCKS_V1_NOT_SEALED")
    pt = (lang == "pt")
    w1 = ({"P1_NOT_FALSIFIED_UNDERPOWERED": "muito além do alcance de hoje", "P1_POWERED": "ao alcance, em poder, de um teste a cinco desvios (afirmação de poder, não de resultado)",
           "P1_FALSIFIED_IN_READING": "falsificada"} if pt else
          {"P1_NOT_FALSIFIED_UNDERPOWERED": "far beyond today's reach", "P1_POWERED": "within the power of a five-sigma test (a statement of power, not of result)",
           "P1_FALSIFIED_IN_READING": "falsified"}).get(p1, "sem veredito nesta rodada" if pt else "without a verdict in this run")
    w2 = ({"P2_EXCLUDED_IN_READING": "excluída pelo LIGO", "P2_NOT_EXCLUDED": "não excluída nesta rodada",
           "P2_AWAITING_DATA": "aguardando o dado (o strain do LIGO não está no cache desta rodada)", "P2_INPUT_INTEGRITY_FAILED": "recusada por integridade do cache",
           "P2_INJECTION_FAILED": "não selada nesta rodada (a injeção de controle reprovou)"} if pt else
          {"P2_EXCLUDED_IN_READING": "excluded by LIGO", "P2_NOT_EXCLUDED": "not excluded in this run",
           "P2_AWAITING_DATA": "awaiting the data (the LIGO strain is not in this run's cache)", "P2_INPUT_INTEGRITY_FAILED": "refused on cache integrity",
           "P2_INJECTION_FAILED": "not sealed in this run (the control injection failed)"}).get(p2, "sem veredito nesta rodada" if pt else "without a verdict in this run")
    ver = (" --- ver o teste dos relógios" if pt else " --- see the clock test")
    if not selado:
        return (r"\emph{(Ao lado, v369: o teste dos relógios não se selou nesta rodada%s.)}" % ver) if pt else (r"\emph{(Beside, v369: the clock test did not seal in this run%s.)}" % ver)
    if onde == "forte":
        return ((r"\emph{(Ao lado, v369: na leitura por partícula, %s; na leitura por modo de luz de cada braço, %s; a partição é [OPEN]%s.)}" % (w1, w2, ver)) if pt else
                (r"\emph{(Beside, v369: in the per-particle reading, %s; in the per-arm light-mode reading, %s; the partition is [OPEN]%s.)}" % (w1, w2, ver)))
    if onde == "raiz":
        exc = bool(rl.get("kbar_zero_excluded") and rl.get("kbar_rest_mass_excluded"))
        return ((r"\emph{(Ao lado, v369: nas unidades do próprio módulo e lida com os níveis de um átomo --- zero no fundamental ou na energia de repouso ---, esta lei %s pela coerência do estrôncio de Kim et al. (2025); ela só reproduz a banda canônica com o nível médio em um quarto da energia de Planck [INPUT], e não é pré-registrável como está.)}"
                 % ("já está excluída" if exc else "não fica excluída nesta rodada")) if pt else
                (r"\emph{(Beside, v369: in the module's own units and read with the levels of an atom --- zero at the ground state or at the rest energy ---, this law is %s by Kim et al.'s strontium coherence (2025); it only reproduces the canonical band with the mean level at one quarter of the Planck energy [INPUT], and it is not pre-registrable as it stands.)}"
                 % ("already excluded" if exc else "not excluded in this run")))
    if onde == "magnitude":
        tc = P1.get("tau_star_bound_clock_95_in_tP"); tb = P1.get("tau_star_bound_best_in_tP")
        bc = P1.get("best_clock_95"); bt = P1.get("tau_star_bound_best_platform")
        fx = lambda x: ((r"%s\times10^{%d}" % ((("%.1f" % (x / 10.0 ** math.floor(math.log10(x)))).replace(".", "{,}") if pt else ("%.1f" % (x / 10.0 ** math.floor(math.log10(x))))),
                                               int(math.floor(math.log10(x))))) if isinstance(x, float) and x > 0 else ("n/d" if pt else "n/a"))
        nao_th = not any(str(x or "").startswith("th229") for x in (bc, bt))
        return ((r"\emph{Ao lado (v369): o limite de $\tau_\star$ hoje vem, entre os relógios com barra de erro verificada, do %s ($\le %s$ tempos de Planck, cota de 95 por cento) e, entre todas as plataformas, do %s ($\le %s$, %s)%s: o que decide é a largura dividida por $\omega^2$. A inclinação $\neq 2$ não tem estimador hoje (todas as plataformas dão só cotas superiores) e não está no CLOCK\_TEST\_V1. Na leitura por partícula a lei está %s; na leitura por modo de luz de cada braço, %s. Ver o teste dos relógios.}"
                 % (_v369_nome(P1, bc, "pt", True), fx(tc), _v369_nome(P1, bt, "pt", True), fx(tb), _v369_tipo(P1.get("tau_star_bound_best_kind"), "pt"),
                    (" --- não do tório" if nao_th else ""), w1, w2)) if pt else
                (r"\emph{Beside (v369): the limit on $\tau_\star$ today comes, among clocks with a verified error bar, from %s ($\le %s$ Planck times, 95 per cent bound) and, among all platforms, from %s ($\le %s$, %s)%s: what decides is the width divided by $\omega^2$. The slope $\neq 2$ has no estimator today (every platform gives only upper bounds) and is not in CLOCK\_TEST\_V1. In the per-particle reading the law is %s; in the per-arm light-mode reading, %s. See the clock test.}"
                 % (_v369_nome(P1, bc, "en", True), fx(tc), _v369_nome(P1, bt, "en", True), fx(tb), _v369_tipo(P1.get("tau_star_bound_best_kind"), "en"),
                    (" --- not from thorium" if nao_th else ""), w1, w2)))
    return ""


def emit_article(core, verdict, data_path, lang):
    if lang == "pt":
        p = os.path.join(OUT, "um_absoluto_pt.tex")
        _tx = _tex_guard_nan(_v394_article_tex(build_pt(core, verdict, data_path), core, 'pt'))
        _write_text_atomic(p, _tx)   # v376: escrita atomica
        _write_text_atomic(os.path.join(OUT, "um_absoluto_pt.txt"), _tex_to_txt(_tx))          # v168: PDF E TXT
        return p
    p = os.path.join(OUT, "um_absoluto_en.tex")
    _tx = _tex_guard_nan(_v394_article_tex(build_en(core, verdict, data_path), core, 'en'))
    _write_text_atomic(p, _tx)   # v376: escrita atomica
    _write_text_atomic(os.path.join(OUT, "um_absoluto_en.txt"), _tex_to_txt(_tx))              # v168: PDF E TXT
    return p


def compile_pdf(texname):
    """v394 PDF tri-state, with explicit MiKTeX offline process options.

    None means pdflatex absent; False means an available engine failed; True
    means both engine passes returned zero and the output PDF exists. In TGL_NO_NETWORK=1 the executable is identified
    by its actual version output before the existing two compilation passes.
    MiKTeX gets options overriding its configuration/registry installer setting
    and disabling write18. This is not an OS network or filesystem sandbox.
    """
    eng = shutil.which("pdflatex")
    if not eng:
        print("   [PDF] pdflatex ausente -> .tex gerado; compile com MiKTeX/TeX Live.")
        return None
    try:
        offline_options = []
        if os.environ.get("TGL_NO_NETWORK") == "1":
            identity = subprocess.run(
                [eng, "--version"], cwd=OUT, capture_output=True,
                text=True, encoding="utf-8", errors="replace", timeout=15)
            if identity.returncode != 0:
                print("   [PDF] nao foi possivel identificar o motor offline.")
                return False
            if "miktex" in (identity.stdout + identity.stderr).lower():
                offline_options = ["--disable-installer", "--disable-write18"]
        for _ in range(2):
            compiled = subprocess.run(
                [eng] + offline_options +
                ["-interaction=nonstopmode", "-halt-on-error", texname + ".tex"],
                cwd=OUT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                timeout=180)
            if compiled.returncode != 0:
                print("   [PDF] motor terminou com codigo %s (ver %s.log)" %
                      (compiled.returncode, texname))
                return False
        ok = os.path.exists(os.path.join(OUT, texname + ".pdf"))
        print("   [PDF] %s.pdf %s" % (
            texname, "OK" if ok else "FALHOU (ver %s.log)" % texname))
        return ok
    except Exception as e:
        print("   [PDF] erro:", e)
        return False


