    r_inf2 = _unvec(Einf @ (Einf @ _vec(rho0)), n)
    idem = float(np.linalg.norm(r_inf2 - r_inf))
    tr_pres = float(abs(np.trace(r_inf).real - 1.0))
    fixed_inv = float(np.linalg.norm(_unvec(Einf @ _vec(rho_star), n) - rho_star))
